&lt;li&gt;&lt;a href=&quot;#_komponen_1_rag_langchain4j_postgresql_pgvector&quot;&gt;Komponen 1 — RAG LangChain4j + PostgreSQL pgvector&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_komponen_2_knowledge_graph_graphify&quot;&gt;Komponen 2 — Knowledge Graph Graphify&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_komponen_3_graphify_inkremental_sparse_dapat_diagregasikan_dapat_dikonsumsi&quot;&gt;Komponen 3 — Graphify Inkremental : Sparse, Dapat Diagregasikan, Dapat Dikonsumsi&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
