&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tahap_2_menulis_ulang_javascript_pengiriman&quot;&gt;Tahap 2 : Menulis ulang JavaScript pengiriman&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ketergantungan_window_firebase&quot;&gt;Ketergantungan `window.&lt;em&gt;FIREBASE&lt;/em&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_baru_contact_js&quot;&gt;Baru `contact.js&lt;/a&gt;&lt;/li&gt;
