}

package &quot;WARM (LAZY)
Dimuat saat diminta
~500 baris&quot; as WARM #FFF9C4 {
  file &quot;SESSIONS_HISTORY
(10 terakhir)&quot; as HIS_WARM
  file &quot;SCRIPT_VERIFICATION\n(terakhir)&quot; as VER_WARM
  file &quot;PROCEDURES.adoc
(templates)&quot; as PRO_WARM
