Tidak pernah diisi
Hanya bacaan manusia&quot; as COLD #BBDEFB {
  folder &quot;Y2026-001-039/&quot; as WAVE {
    file &quot;INDEX (lengkap)&quot; as IDX_COLD
    file &quot;SESSIONS_HISTORY
(lengkap)&quot; as HIS_COLD
    file &quot;COMPLETED_TASKS\n(selesai)&quot; as ARCH_COLD
    folder &quot;sesi/ (001-039)&quot; as SESS_COLD
  }
