&lt;li&gt;&lt;a href=&quot;#_apa_yang_kita_dapatkan_pada_akhirnya&quot;&gt;Apa yang kita dapatkan pada akhirnya&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tautan&quot;&gt;tautan&lt;/a&gt;&lt;/li&gt;
