&lt;li&gt;&lt;a href=&quot;#_percobaan_2_ekstensi_custom_css_and_js_loader&quot;&gt;Percobaan 2 : ekstensi Custom CSS and JS Loader&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_jebakan_anda_harus_mengaktifkan_ekstensi_setiap_kali&quot;&gt;Jebakan: Anda harus mengaktifkan ekstensi setiap kali&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_percobaan_3_garis_garis_saling_tumpang_tindih&quot;&gt;Percobaan 3 : garis-garis saling tumpang tindih&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_solusi_zoom_pada_kontainer_induk&quot;&gt;Solusi: &lt;code&gt;zoom&lt;/code&gt; pada kontainer induk&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ringkasan_selector_dan_apa_yang_berfungsi&quot;&gt;Ringkasan selector dan apa yang berfungsi&lt;/a&gt;&lt;/li&gt;
