&lt;li&gt;&lt;a href=&quot;#_langkah_6_memeriksa_ekstensi_proyek&quot;&gt;Langkah 6: memeriksa ekstensi proyek&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ringkasan_metode&quot;&gt;Ringkasan metode&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
