&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_visi_arkitektonik&quot;&gt;Visi Arkitektonik&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prinsip_pedoman&quot;&gt;Prinsip pedoman&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur didasarkan pada prinsip &lt;strong&gt;pemisahan perhatian&lt;/strong&gt; :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Konten&lt;/strong&gt; : file AsciiDoc terstruktur dengan metadata kaya&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Presentasi&lt;/strong&gt; : templates Thymeleaf yang dapat digunakan kembali&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Data&lt;/strong&gt; : model diekstrak otomatis oleh JBake dari atribut AsciiDoc&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Gaya&lt;/strong&gt; : Bootstrap 5 untuk konsistensi visual&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_pilihan_strategis_asciidoc_untuk_portofolio&quot;&gt;Pilihan strategis : AsciiDoc untuk portofolio&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;caption class=&quot;title&quot;&gt;Table 1. Mengapa AsciiDoc ?&lt;/caption&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 66.6667%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;kriteria&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;keuntungan&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Konsistensi&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Format yang sama dengan artikel blog&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;metadata&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Atribut terstruktur dan dapat diperluas`project-*`)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Kemudahan pemeliharaan&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Pengeditan teks sederhana, dapat di-versi dengan Git&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;fleksibilitas&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Mungkin mengandung konten kaya (tabel, kode, gambar)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;pembuatan template&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;JBake mengekstrak secara otomatis atribut untuk Thymeleaf&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_model_data&quot;&gt;Model data&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Setiap proyek portofolio adalah dokumen AsciiDoc dengan :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Metadata header&lt;/strong&gt; : informasi terstruktur (klien, durasi, teknologi, dll)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Badan dokumen&lt;/strong&gt; : deskripsi naratif, tantangan, solusi, hasil&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Atribut kustom&lt;/strong&gt; : berawalan`project-*`untuk ekstraksi otomatis&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam handwritten false

class ProjetAsciiDoc {
  +titre: String
  +jbake-type: &quot;proyek&quot;
  +jbake-status: published|draft
  +jbake-date: Date
  +jbake-tags: List&amp;lt;String&amp;gt;
  --
  +project-category: String
  +project-client: String
  +project-duration: String
  +project-role: String
  +project-thumbnail: String
  +project-gallery: List&amp;lt;String&amp;gt;
  +project-tech-stack: String
  +project-highlights: List&amp;lt;String&amp;gt;
  +project-demo-url: String
  +project-github-url: String
  --
  +body: HTML (converti)
}

class JBakeEngine {
  +parse(asciidoc)
  +extractMetadata()
  +convertToHTML()
}

class ThymeleafTemplate {
  +portfolio.html
  +project.html
  +partials/project-card.html
}

class PortfolioPage {
  +published_projects: List
  +filtres: categories
}

ProjetAsciiDoc --&amp;gt; JBakeEngine : parse
JBakeEngine --&amp;gt; ThymeleafTemplate : fournit données
ThymeleafTemplate --&amp;gt; PortfolioPage : génère
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_use_cases_rinci&quot;&gt;Use Cases Rinci&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc1_menambahkan_sebuah_elemen_ke_dalam_portofolio&quot;&gt;UC1 : Menambahkan sebuah elemen ke dalam portofolio&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_aliran_nominal&quot;&gt;Aliran nominal&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;Editor
Teks&quot; as editor
participant &quot;File
AsciiDoc&quot; as file
participant &quot;JBake\nmesin&quot; as jbake
participant &quot;Situs\nStatis&quot; as site

dev -&amp;gt; editor : Créer nouveau fichier
activate editor
editor -&amp;gt; file : portfolio/nouveau-projet.adoc
activate file

dev -&amp;gt; editor : Rédiger en-tête avec métadonnées\n(titre, type=project, status=published,\nattributs project-*)
dev -&amp;gt; editor : Rédiger contenu narratif\n(contexte, défis, solutions)
dev -&amp;gt; editor : Ajouter images dans assets/img/portfolio/

editor -&amp;gt; file : Sauvegarder
deactivate editor

dev -&amp;gt; jbake : Lancer build (jbake -b)
activate jbake
jbake -&amp;gt; file : Lire et parser
jbake -&amp;gt; jbake : Extraire métadonnées
jbake -&amp;gt; jbake : Convertir AsciiDoc → HTML
jbake -&amp;gt; jbake : Appliquer template project.html
jbake -&amp;gt; jbake : Ajouter à la liste portfolio.html
jbake -&amp;gt; site : Générer pages statiques
deactivate jbake

dev -&amp;gt; site : Vérifier résultat
activate site
site --&amp;gt; dev : Afficher projet
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_template_file_yang_akan_dibuat&quot;&gt;Template file yang akan dibuat&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Pengembang membuat`content/portfolio/nom-projet.adoc`dengan struktur yang terstandar :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Header dengan semua atribut yang diperlukan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sections terstandar (Konteks, Tantangan, Solusi, Hasil)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Penamaan gambar yang konsisten&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_poin_validasi&quot;&gt;Poin validasi&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Atribut yang diperlukan ada (&lt;code&gt;jbake-type&lt;/code&gt;, &lt;code&gt;jbake-status&lt;/code&gt;, &lt;code&gt;project-thumbnail&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Gambar yang dirujuk ada di`assets/img/portfolio/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Build JBake berhasil tanpa kesalahan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Proyek muncul di halaman portofolio&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Halaman individual proyek ditampilkan dengan benar&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc2_menghapus_sebuah_elemen_dari_portofolio&quot;&gt;UC2 : Menghapus sebuah elemen dari portofolio&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_fluks_nominal&quot;&gt;fluks nominal&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;Sistem
File&quot; as fs
participant &quot;JBake
Engine&quot; as jbake
participant &quot;Situs\nStatis&quot; as site
database &quot;Cache\nJBake&quot; as cache

dev -&amp;gt; fs : Supprimer portfolio/projet-ancien.adoc
activate fs
fs --&amp;gt; dev : Fichier supprimé
deactivate fs

dev -&amp;gt; fs : (Optionnel) Supprimer images associées\nassets/img/portfolio/projet-ancien-*
activate fs
fs --&amp;gt; dev : Images supprimées
deactivate fs

dev -&amp;gt; cache : Nettoyer cache JBake
activate cache
cache --&amp;gt; dev : Cache vidé
deactivate cache

dev -&amp;gt; jbake : Rebuild complet (jbake -b)
activate jbake
jbake -&amp;gt; jbake : Scanner content/portfolio/
jbake -&amp;gt; jbake : Projet absent → non généré
jbake -&amp;gt; jbake : Régénérer portfolio.html\n(sans le projet supprimé)
jbake -&amp;gt; site : Déployer nouveau build
deactivate jbake

dev -&amp;gt; site : Vérifier
activate site
site --&amp;gt; dev : Projet absent de la liste
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_strategi_alternatif_pengarsipan&quot;&gt;Strategi alternatif: pengarsipan&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Alih-alih menghapus secara permanen, ada kemungkinan untuk membuat folder`content/portfolio/archive/`(Empty output)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Pindahkan file alih-alih menghapusnya&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Memudahkan pemulihan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Jaga riwayat Git lebih jelas&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_pembersihan_sumber_daya&quot;&gt;Pembersihan sumber daya&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Memeriksa gambar yatim di`assets/img/portfolio/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Hapus gambar yang tidak dirujuk oleh proyek lain&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Membersihkan cache JBake untuk menghindari referensi hantu&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc3_menetapkan_sebagai_tidak_dipublikasikan_draft&quot;&gt;UC3 : Menetapkan sebagai tidak dipublikasikan (draft)&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_fluks_nominal_2&quot;&gt;Fluks nominal&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;File
AsciiDoc&quot; as file
participant &quot;JBake\nMesin&quot; as jbake
participant &quot;Site
Statis&quot; as site

dev -&amp;gt; file : Ouvrir portfolio/projet.adoc
activate file

dev -&amp;gt; file : Modifier attribut\n:jbake-status: published\n↓\n:jbake-status: draft

file --&amp;gt; dev : Sauvegardé
deactivate file

dev -&amp;gt; jbake : Rebuild (jbake -b)
activate jbake
jbake -&amp;gt; file : Parser le fichier
jbake -&amp;gt; jbake : Détecter status=draft
jbake -&amp;gt; jbake : Exclure de published_projects
jbake -&amp;gt; jbake : Ne pas créer page publique
note right
  Le projet existe toujours
  mais n&#39;est pas publié
end note
jbake -&amp;gt; site : Générer site (sans ce projet)
deactivate jbake

dev -&amp;gt; site : Vérifier portfolio
activate site
site --&amp;gt; dev : Projet absent de la liste publique
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_status_yang_mungkin&quot;&gt;status yang mungkin&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

[*] --&amp;gt; Draft : Création initiale
Draft --&amp;gt; Published : Validation et publication
Published --&amp;gt; Draft : Retrait temporaire
Draft --&amp;gt; Archived : Projet abandonné
Published --&amp;gt; Archived : Projet obsolète
Archived --&amp;gt; [*] : Suppression définitive
Published --&amp;gt; Published : Mises à jour

note right of Draft
  :jbake-status: draft
  Non visible publiquement
  Utile pour projets en cours
end note

note right of Published
  :jbake-status: published
  Visible sur le portfolio
  Indexé par JBake
end note

note right of Archived
  Déplacé dans archive/
  ou jbake-status: archived
  Non publié mais conservé
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_kasus_penggunaan_tipikal&quot;&gt;Kasus penggunaan tipikal&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Proyek yang sedang dalam proses penulisan&lt;/strong&gt; : membuat sebagai draft, publikasikan ketika sudah selesai&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Proyek rahasia sementara&lt;/strong&gt; : beralih ke draft sampai persetujuan klien&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Pembaruan besar&lt;/strong&gt; : beralih ke draft, mengedit, menerbitkan kembali&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;A/B testing&lt;/strong&gt; : duplikasi dalam draft, uji, terbitkan versi terbaik&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_arsitektur_templating&quot;&gt;Arsitektur Templating&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_strategi_template_yang_dapat_digunakan_kembali&quot;&gt;Strategi template yang dapat digunakan kembali&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Template Thymeleaf&quot; {
  component [index.html] as index
  component [portfolio.html] as portfolio
  component [project.html] as project

  package &quot;parsial&quot; {
    component [header.html] as header
    component [footer.html] as footer
    component [project-card.html] as card
    component [tech-badge.html] as badge
    component [gallery.html] as gallery
  }
}

package &quot;Data JBake&quot; {
  database &quot;proyek_dipublikasikan&quot; as data
  database &quot;(proyek)&quot; as content
}

index --&amp;gt; header
index --&amp;gt; footer

portfolio --&amp;gt; header
portfolio --&amp;gt; footer
portfolio --&amp;gt; card
data --&amp;gt; portfolio : itération

project --&amp;gt; header
project --&amp;gt; footer
project --&amp;gt; badge
project --&amp;gt; gallery
content --&amp;gt; project : projet individuel

note right of card
  Fragment réutilisable
  pour afficher une carte
  de projet avec :
  - thumbnail
  - titre
  - tags
  - highlights
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_pola_ekstraksi_data&quot;&gt;Pola ekstraksi data&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake secara otomatis mengubah atribut AsciiDoc menjadi properti yang dapat diakses di Thymeleaf :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Dokumen AsciiDoc&quot; {
  (&quot;:project-client: Acme Corp&quot;) as attr1
  (&quot;:project-duration: 6 bulan&quot;) as attr2
  (&quot;:project-tags: java, react&quot;) as attr3
}

rectangle &quot;Model JBake&quot; {
  (content[&#39;project-client&#39;]) as prop1
  (content[&#39;project-duration&#39;]) as prop2
  (content.tags) as prop3
}

rectangle &quot;Template Thymeleaf&quot; {
  (th:text=&quot;${project[&#39;project-client&#39;]}&quot;) as tmpl1
  (th:text=&quot;${project[&#39;project-duration&#39;]}&quot;) as tmpl2
  (th:each=&quot;tag : ${project.tags}&quot;) as tmpl3
}

attr1 --&amp;gt; prop1 : parsing
attr2 --&amp;gt; prop2 : parsing
attr3 --&amp;gt; prop3 : parsing

prop1 --&amp;gt; tmpl1 : binding
prop2 --&amp;gt; tmpl2 : binding
prop3 --&amp;gt; tmpl3 : binding
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_konvensi_penamaan&quot;&gt;Konvensi penamaan&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Atribut proyek&lt;/strong&gt; : awalan`project-*` (ex: &lt;code&gt;project-client&lt;/code&gt;, &lt;code&gt;project-tech-stack&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Berkas&lt;/strong&gt; : kebab-case (ex:`ecommerce-platform.adoc`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Images&lt;/strong&gt; : awalan nama-proyek (contoh:`ecommerce-platform-thumb.jpg`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Templates&lt;/strong&gt; : nama fungsional (contoh:`project-card.html`, &lt;code&gt;tech-badge.html&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_alur_kerja_publikasi&quot;&gt;Alur Kerja Publikasi&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_alur_pengembangan&quot;&gt;Alur pengembangan&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam handwritten false

class ProjetAsciiDoc {
  +titre: String
  +jbake-type: &quot;proyek&quot;
  +jbake-status: published|draft
  +jbake-date: Date
  +jbake-tags: List&amp;lt;String&amp;gt;
  __
  +project-category: String
  +project-client: String
  +project-duration: String
  +project-role: String
  +project-thumbnail: String
  +project-gallery: List&amp;lt;String&amp;gt;
  +project-tech-stack: String
  +project-highlights: List&amp;lt;String&amp;gt;
  +project-demo-url: String
  +project-github-url: String
  __
  +body: HTML (converti)
}

class JBakeEngine {
  +parse(asciidoc)
  +extractMetadata()
  +convertToHTML()
}

class ThymeleafTemplate {
  +portfolio.html
  +project.html
  +partials/project-card.html
}

class PortfolioPage {
  +published_projects: List
  +filtres: categories
}

ProjetAsciiDoc --&amp;gt; JBakeEngine : parse
JBakeEngine --&amp;gt; ThymeleafTemplate : fournit données
ThymeleafTemplate --&amp;gt; PortfolioPage : génère
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_lingkungan&quot;&gt;lingkungan&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 20%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Lingkungan&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Penggunaan&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Status diterima&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;lokal&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Pengembangan dan pratinjau&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;draft, diterbitkan&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;penataan&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Validasi pra-produksi&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;diterbitkan hanya&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Produksi&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Situs publik&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;diterbitkan hanya&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ekstensibilitas&quot;&gt;ekstensibilitas&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_penambahan_atribut_baru&quot;&gt;Penambahan atribut baru&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Untuk memperkaya model data, cukup menambahkan atribut baru yang diawali`project-*`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;`project-awards`Harga dan Penghargaan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-testimonial&lt;/code&gt;: Kutipan klien&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-team-size&lt;/code&gt;: Ukuran tim&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-budget-range&lt;/code&gt;: jangka anggaran&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Atribut-atribut ini secara otomatis tersedia di dalam template tanpa modifikasi mesin JBake.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kategorisasi_lanjutan&quot;&gt;Kategorisasi lanjutan&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

object Projet {
  project-category = &quot;web&quot;
  project-subcategory = &quot;perdagangan elektronik&quot;
  project-industry = &quot;ritel&quot;
  project-complexity = &quot;tinggi&quot;
}

object Taxonomie {
  categories : [web, mobile, data, devops]
  subcategories : Map&amp;lt;category, List&amp;gt;
  industries : [retail, finance, healthcare, ...]
  complexities : [low, medium, high]
}

Projet --&amp;gt; Taxonomie : classifié selon

note right of Taxonomie
  Permet filtrage multi-critères
  dans le template portfolio.html
  via JavaScript ou côté serveur
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_praktik_baik&quot;&gt;Praktik Baik&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_organisasi_file&quot;&gt;Organisasi file&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Satu file = satu proyek&lt;/strong&gt; : hindari mencampurkan beberapa proyek&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Gambar di folder khusus&lt;/strong&gt; :`assets/img/portfolio/nom-projet/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Nomenklatur konsisten&lt;/strong&gt; : memudahkan pencarian dan pemeliharaan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Versioning Git&lt;/strong&gt; : pelacakan lengkap perubahan&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_manajemen_konten&quot;&gt;Manajemen konten&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Status draft secara default&lt;/strong&gt; : hanya menerbitkan ketika siap&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Tinjauan sebelum publikasi&lt;/strong&gt; : validasi kualitas dan kerahasiaan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Metadata lengkap&lt;/strong&gt; : mengisi semua kolom yang relevan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Konten naratif kaya&lt;/strong&gt;: tidak membatasi diri pada metadata&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kinerja&quot;&gt;kinerja&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Mengoptimalkan gambar&lt;/strong&gt; : kompresi sebelum commit&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Pagination yang diperlukan&lt;/strong&gt; : jika &amp;gt;20 proyek&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Lazy loading&lt;/strong&gt; : gambar galeri yang dimuat saat diperlukan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Cache peramban&lt;/strong&gt; : header yang sesuai untuk aset&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_kesimpulan&quot;&gt;Kesimpulan&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur ini memungkinkan:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Kemudahan penggunaan&lt;/strong&gt; : menambahkan proyek = membuat file teks&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Kefleksibilitas&lt;/strong&gt; : dapat diperluas melalui atribut baru&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Kemudahan pemeliharaan&lt;/strong&gt; : pemisahan konten/presentasi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;pelacakan&lt;/strong&gt; : versioning Git lengkap&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Otomatisasi&lt;/strong&gt; : pembangunan dan penyebaran kontinu mungkin&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Pemilihan AsciiDoc menjamin konsistensi dengan sisanya situs sambil memberikan kekayaan metadata yang diperlukan untuk portofolio profesional.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;waktu membaca : 12 minutes&lt;/div&gt;
&lt;p&gt;Alih-alih memilih antara kesederhanaan Supabase dan kekuatan Spring Boot, mengapa tidak menggabungkan keduanya? Temukan arsitektur hibrid yang memanfaatkan yang terbaik dari setiap teknologi.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;gangguan obsesif-kompulsi&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_dilema_palsu_arsitektur_modern&quot;&gt;Dilema Palsu Arsitektur Modern&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Saat membangun aplikasi modern dengan frontend statis, kita sering menemukan diri kita dihadapkan pada pilihan biner :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Menaruh seluruh harapan pada solusi Backend-as-a-Service&lt;/strong&gt;(Supabase, Firebase) - sederhana namun terbatas&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Membangun backend lengkap&lt;/strong&gt;(Spring Boot, Node.js) - kuat namun kompleks&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Pilihan ini adalah dilemma palsu. Arsitektur hibrid menawarkan jalan ketiga: &lt;strong&gt;menggunakan setiap teknologi di mana iaExcels&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_visi_arsitektur&quot;&gt;Visi Arsitektur&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_arsitektur_tradisional_monolitik&quot;&gt;Arsitektur Tradisional: Monolitik&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Arsitektur Tradisional&quot; {
  actor Utilisateur as user
  component &quot;frontend&quot; as frontend #LightBlue
  component &quot;Backend monolitik&quot; as backend #LightCoral {
    [Authentification]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [APIs Tierces]
  }
  database &quot;Basis Data&quot; as db #LightGray

  user --&amp;gt; frontend
  frontend --&amp;gt; backend : Toutes les requêtes
  backend --&amp;gt; db
}

note right of backend
  Tout passe par le backend
  même les opérations simples

  ⚠️ Point de congestion unique
  ⚠️ Complexité dès le départ
  ⚠️ Couplage fort
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dalam pendekatan ini, bahkan operasi-operasi paling sederhana (membaca artikel, membuat komentar) harus melewati backend Anda. Anda membayar biaya kompleksitas sejak hari pertama.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_arsitektur_baas_semua_delegat&quot;&gt;Arsitektur BaaS: Semua Delegat&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Arsitektur BaaS Murni&quot; {
  actor Utilisateur as user
  component &quot;Frontend&quot; as frontend #LightBlue
  cloud &quot;Supabase / Firebase&quot; as baas #LightGreen {
    [Auth]
    [Database]
    [Storage]
    [Edge Functions]
  }

  user --&amp;gt; frontend
  frontend --&amp;gt; baas : Toutes les opérations
}

note right of baas
  Développement rapide
  Pas de serveur à gérer

  ⚠️ Limité pour logique complexe
  ⚠️ Vendor lock-in
  ⚠️ Edge Functions contraintes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Di sisi lain, mendelegasikan semuanya ke BaaS menarik di awal, tetapi menunjukkan batasnya dengan cepat begitu logika bisnis menjadi kompleks.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_arsitektur_hibrid_pemisahan_tanggung_jawab&quot;&gt;Arsitektur Hibrid : Pemisahan Tanggung Jawab&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Utilisateur as user #LightBlue

package &quot;Lapisan Frontend&quot; {
  component &quot;Situs Statis JBake&quot; as frontend #SkyBlue
}

package &quot;Lapisan Sederhana (Supabase)&quot; #LightGreen {
  component &quot;Authentifikasi&quot; as auth
  component &quot;CRUD Dasar&quot; as crud
  component &quot;Penyimpanan File&quot; as storage
  component &quot;Waktu nyata&quot; as realtime
}

package &quot;Lapisan Bisnis (Spring Boot)&quot; #Coral {
  component &quot;Logika Kompleks&quot; as logic
  component &quot;Orkestrasi&quot; as orchestration
  component &quot;Pekerjaan Terjadwal&quot; as jobs
  component &quot;Integrasi&quot; as integrations
}

database &quot;PostgreSQL Dibagikan&quot; as db #LightGray

user --&amp;gt; frontend

frontend --&amp;gt; auth : OAuth2, JWT
frontend --&amp;gt; crud : Articles, Profils
frontend --&amp;gt; storage : Images, Fichiers
frontend --&amp;gt; realtime : Notifications

frontend --&amp;gt; logic : Calculs, Rapports
frontend --&amp;gt; orchestration : Workflows
logic --&amp;gt; integrations : Stripe, APIs
orchestration --&amp;gt; db
jobs --&amp;gt; db

crud --&amp;gt; db
auth --&amp;gt; db

note bottom of db
  **Une seule source de vérité**
  Partagée entre Supabase et Spring Boot
end note

note right of auth
  **Gratuit jusqu&#39;à 50k users**
  Configuration en quelques clics
  OAuth2 multi-providers
end note

note right of logic
  **Activé seulement si nécessaire**
  Kotlin + Coroutines
  Transactions complexes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur hibrid dengan jelas memisahkan tanggung jawab berdasarkan kompleksitas dan sifat operasi.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_prinsip_desain&quot;&gt;Prinsip Desain&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prinsip_1_mulai_sederhana_berkembang_secara_cerdas&quot;&gt;Prinsip 1: Mulai Sederhana, Berkembang Secara Cerdas&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;**Tahap 1 : MVP**&quot; #LightGreen {
  component &quot;JBake + Supabase&quot; as mvp
  note right
    ✓ Développement en jours
    ✓ Coût : 0€
    ✓ Validation concept
  end note
}

rectangle &quot;Fase 2 : Pertumbuhan&quot; #LightYellow {
  component &quot;JBake + Supabase\n+ Spring Boot (opsional)&quot; as growth
  note right
    ✓ Logique métier émerge
    ✓ Premiers jobs planifiés
    ✓ Intégrations tierces
  end note
}

rectangle &quot;Fase 3 : Skala&quot; #LightCoral {
  component &quot;Arsitektur lengkap&quot; as scale
  note right
    ✓ Orchestration complexe
    ✓ Performances optimisées
    ✓ Cache distribué
  end note
}

mvp -down-&amp;gt; growth : Quand la complexité\nle justifie
growth -down-&amp;gt; scale : Optimisation\ncontinue
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Jangan membangun Spring Boot jika Anda tidak membutuhkannya.&lt;/strong&gt;Mulai dengan Supabase, tambahkan Spring Boot ketika kompleksitas membenarkannya.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prinsip_2_pemisahan_berdasarkan_jenis_operasi&quot;&gt;Prinsip 2 : Pemisahan Berdasarkan Jenis Operasi&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Opérations\nApplicatives

left side

** Opérations Simples\n(Supabase)
***_ CRUD Standard
****_ Lecture
****_ Création
****_ Mise à jour
****_ Suppression
***_ Authentification
****_ Login/Logout
****_ OAuth2
****_ Gestion session
***_ Stockage
****_ Upload fichiers
****_ CDN automatique
***_ Temps Réel
****_ WebSocket
****_ Notifications

right side

** Opérations Complexes\n(Spring Boot)
***_ Logique Métier
****_ Calculs complexes
****_ Règles métier
****_ Validations avancées
***_ Orchestration
****_ Multi-services
****_ Transactions distribuées
****_ Saga patterns
***_ Tâches Planifiées
****_ Rapports périodiques
****_ Synchronisations
****_ Nettoyages
***_ Intégrations
****_ Paiements (Stripe)
****_ APIs tierces
****_ Services ML/AI

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prinsip_3_satu_sumber_kebenaran&quot;&gt;Prinsip 3: Satu Sumber Kebenaran&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

database &quot;PostgreSQL&quot; as db #LightGray {
  package &quot;Skema: auth (Supabase)&quot; #LightGreen {
    [users]
    [sessions]
    [identities]
  }

  package &quot;Skema: Publik (Dibagikan)&quot; #SkyBlue {
    [articles]
    [comments]
    [profiles]
  }

  package &quot;Schema: business (Spring Boot)&quot; #Coral {
    [orders]
    [payments]
    [reports]
  }
}

component &quot;Supabase&quot; as supabase #LightGreen
component &quot;Spring Boot&quot; as spring #Coral

supabase -down-&amp;gt; users : Gère
supabase -down-&amp;gt; sessions : Gère
supabase -down-&amp;gt; articles : Accède
supabase -down-&amp;gt; comments : Accède
supabase -down-&amp;gt; profiles : Accède

spring -down-&amp;gt; articles : Accède
spring -down-&amp;gt; profiles : Accède
spring -down-&amp;gt; orders : Gère
spring -down-&amp;gt; payments : Gère
spring -down-&amp;gt; reports : Gère

note right of db
  **Avantages :**
  • Pas de synchronisation complexe
  • JOINs possibles entre tables
  • Cohérence garantie
  • Migrations unifiées
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dengan berbagi instance PostgreSQL yang sama, Supabase dan Spring Boot bekerja pada data yang sama tanpa sinkronisasi kompleks.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_orchestrasi_aliran&quot;&gt;Orchestrasi aliran&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_aliran_1_otentikasi_terpusat&quot;&gt;Aliran 1 : Otentikasi Terpusat&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;pengguna&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Supabase Auth&quot; as auth
participant &quot;Spring Boot&quot; as spring
database &quot;PostgreSQL&quot; as db

== Authentification ==
user -&amp;gt; jbake : Clique &quot;Masuk&quot;
jbake -&amp;gt; auth : Redirect OAuth2 (Google/GitHub)
auth -&amp;gt; user : Consent screen
user -&amp;gt; auth : Autorise
auth -&amp;gt; auth : Génère JWT
auth -&amp;gt; jbake : Retourne JWT + Refresh Token
jbake -&amp;gt; jbake : Stocke tokens (sessionStorage)

== Accès aux Ressources ==
group Opération Simple (CRUD)
  user -&amp;gt; jbake : Crée un article
  jbake -&amp;gt; db : POST avec JWT
  note right: Supabase Row Level Security\nvérifie le JWT automatiquement
  db -&amp;gt; jbake : Article créé
end

group Opération Complexe (Métier)
  user -&amp;gt; jbake : Génère un rapport
  jbake -&amp;gt; spring : POST /api/reports\navec JWT
  spring -&amp;gt; spring : Valide JWT Supabase
  spring -&amp;gt; spring : Extrait claims (user_id, roles)
  spring -&amp;gt; db : Requêtes complexes
  spring -&amp;gt; jbake : Rapport généré
end

note over auth, spring
  **Le JWT est universel**
  Valide par Supabase ET Spring Boot
  Pas de double authentification
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Poin kunci&lt;/strong&gt;: Satu proses otentikasi, satu JWT, dapat digunakan di mana pun.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_alur_2_orkesstraksi_proses_bisnis_kompleks&quot;&gt;Alur 2: Orkesstraksi Proses Bisnis Kompleks&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;Klien&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Spring Boot&quot; as spring
participant &quot;Supabase DB&quot; as supadb
participant &quot;Stripe API&quot; as stripe
participant &quot;Layanan Persediaan&quot; as inventory
participant &quot;Layanan Email&quot; as email
database &quot;PostgreSQL&quot; as db

user -&amp;gt; jbake : Passe commande
jbake -&amp;gt; spring : POST /api/orders/create

== Orchestration Spring Boot ==
spring -&amp;gt; db : BEGIN TRANSACTION

par Vérifications Parallèles
  spring -&amp;gt; inventory : Vérifier stock
  inventory -&amp;gt; spring : Stock OK
else
  spring -&amp;gt; db : Vérifier profil client
  db -&amp;gt; spring : Client vérifié
end

spring -&amp;gt; stripe : Créer Payment Intent
stripe -&amp;gt; spring : Intent créé (ID: pi_xxx)

spring -&amp;gt; db : Créer Order (status: PENDING)
db -&amp;gt; spring : Order créé

spring -&amp;gt; stripe : Confirmer paiement
stripe -&amp;gt; spring : Paiement confirmé

spring -&amp;gt; db : Update Order (status: PAID)
spring -&amp;gt; inventory : Décrémenter stock
spring -&amp;gt; db : COMMIT TRANSACTION

par Notifications Asynchrones
  spring -&amp;gt; email : Email confirmation
else
  spring -&amp;gt; supadb : Insert notification
  note right: Notification temps réel\nvia Supabase Realtime
end

spring -&amp;gt; jbake : Order confirmé
jbake -&amp;gt; user : Affiche confirmation

note over spring
  **Responsabilités Spring Boot :**
  • Transaction ACID
  • Orchestration multi-services
  • Rollback automatique si erreur
  • Gestion des cas limites
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Apa yang Spring Boot bawa&lt;/strong&gt;: Orkestrasi yang andal dari proses kompleks yang melibatkan beberapa sistem dengan jaminan transaksional.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_flux_3_tugas_terjadwal_dan_sinkronisasi&quot;&gt;Flux 3 : Tugas Terjadwal dan Sinkronisasi&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

participant &quot;Penjadwal
(Spring Boot)&quot; as scheduler
participant &quot;layanan laporan&quot; as report
participant &quot;PostgreSQL&quot; as db
participant &quot;API eksternal&quot; as api
participant &quot;Layanan Email&quot; as email
participant &quot;Supabase Storage&quot; as storage

== Job Quotidien : 2h00 ==
activate scheduler
scheduler -&amp;gt; report : Déclenche génération rapport

activate report
report -&amp;gt; db : Récupère données\ndes dernières 24h
db -&amp;gt; report : Dataset

report -&amp;gt; report : Calculs &amp;amp; Agrégations
report -&amp;gt; report : Génération PDF

report -&amp;gt; storage : Upload PDF
storage -&amp;gt; report : URL publique

report -&amp;gt; email : Envoie aux admins\navec lien PDF
deactivate report

== Job Hebdomadaire : Dimanche 3h00 ==
scheduler -&amp;gt; report : Synchronisation externe

activate report
report -&amp;gt; api : Fetch données externes
api -&amp;gt; report : Nouvelles données

report -&amp;gt; db : Mise à jour tables
report -&amp;gt; db : Nettoyage données obsolètes
deactivate report

== Job Mensuel : 1er du mois ==
scheduler -&amp;gt; report : Facturation

activate report
report -&amp;gt; db : Liste clients actifs
report -&amp;gt; report : Calcul montants
report -&amp;gt; api : Génération factures (Stripe)
report -&amp;gt; email : Envoi factures
deactivate report

deactivate scheduler

note right of scheduler
  **Impossible avec Supabase seul**
  Edge Functions non adaptées
  pour jobs longs et récurrents
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Apa yang dibawa Spring Boot&lt;/strong&gt;: Pekerjaan terjadwal yang andal dengan manajemen status, percobaan otomatis, dan eksekusi terjamin.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_matriks_keputusan&quot;&gt;Matriks Keputusan&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kapan_menggunakan_supabase&quot;&gt;Kapan Menggunakan Supabase ?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité à implémenter;

if (CRUD simple ?) then (oui)
  :✅ **Supabase**;
  stop
else (non)
  if (Authentification ?) then (oui)
    :✅ **Supabase Auth**;
    stop
  else (non)
    if (Upload fichiers ?) then (oui)
      :✅ **Supabase Storage**;
      stop
    else (non)
      if (Temps réel ?) then (oui)
        :✅ **Supabase Realtime**;
        stop
      else (non)
        if (Row Level Security\nsuffisante ?) then (oui)
          :✅ **Supabase + Policies**;
          stop
        else (non)
          :⚠️ **Considérer Spring Boot**;
          #Coral:Passer à l&#39;arbre\nde décision Spring Boot;
          stop
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kapan_harus_menggunakan_spring_boot&quot;&gt;Kapan harus menggunakan Spring Boot ?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité complexe;

if (Orchestration\nmulti-services ?) then (oui)
  :✅ **Spring Boot**;
  stop
else (non)
  if (Transaction ACID\ncritique ?) then (oui)
    :✅ **Spring Boot**;
    stop
  else (non)
    if (Job planifié ?) then (oui)
      :✅ **Spring Boot Scheduler**;
      stop
    else (non)
      if (Intégration API\ntierce complexe ?) then (oui)
        :✅ **Spring Boot**;
        stop
      else (non)
        if (Calculs lourds\n&amp;gt; 10 secondes ?) then (oui)
          :✅ **Spring Boot**;
          stop
        else (non)
          if (Cache distribué\nnécessaire ?) then (oui)
            :✅ **Spring Boot + Redis**;
            stop
          else (non)
            :⚠️ **Probablement Supabase**;
            #LightGreen:Revenir à l&#39;arbre\nde décision Supabase;
            stop
          endif
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_contoh_arsitektur_berdasarkan_tipe_proyek&quot;&gt;Contoh Arsitektur berdasarkan Tipe Proyek&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_blog_portofolio&quot;&gt;Blog / Portofolio&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Blog Pribadi - 95% Supabase&quot; {
  component &quot;JBake&quot; as jbake #SkyBlue

  package &quot;Supabase (Gratis)&quot; #LightGreen {
    [Auth: OAuth2 Google]
    [Articles (CRUD)]
    [Commentaires]
    [Images (Storage)]
    [Notifications Realtime]
  }

  package &quot;Spring Boot (Opsional)&quot; #LightCoral {
    [Newsletter Mensuelle]
    note bottom: Job planifié uniquement
  }

  database &quot;PostgreSQL&quot; as db

  jbake --&amp;gt; [Auth: OAuth2 Google]
  jbake --&amp;gt; [Articles (CRUD)]
  jbake --&amp;gt; [Commentaires]
  jbake --&amp;gt; [Images (Storage)]
  jbake --&amp;gt; [Notifications Realtime]

  [Articles (CRUD)] --&amp;gt; db
  [Commentaires] --&amp;gt; db
  [Newsletter Mensuelle] --&amp;gt; db
}

note bottom of &quot;Spring Boot (Opsional)&quot;
  **Spring Boot pas obligatoire**
  Newsletter peut être gérée
  par un service tiers (Mailchimp)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Putusan&lt;/strong&gt;: 100% Supabase lebih-than cukup.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_aplikasi_saas&quot;&gt;Aplikasi SaaS&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Aplikasi SaaS - Arsitektur Hibrid&quot; {
  component &quot;JBake / React&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Multi-tenant]
    [Profils Utilisateurs]
    [Données Simples]
    [Storage Documents]
  }

  package &quot;Spring Boot&quot; #Coral {
    [Facturation (Stripe)]
    [Analytics Avancées]
    [Rapports Mensuels]
    [Quotas &amp;amp; Limites]
    [Webhooks Stripe]
  }

  cloud &quot;Layanan Eksternal&quot; {
    [Stripe API]
    [SendGrid Email]
  }

  database &quot;PostgreSQL Dibagikan&quot; as db

  frontend --&amp;gt; [Auth Multi-tenant]
  frontend --&amp;gt; [Profils Utilisateurs]
  frontend --&amp;gt; [Données Simples]
  frontend --&amp;gt; [Facturation (Stripe)]
  frontend --&amp;gt; [Analytics Avancées]

  [Auth Multi-tenant] --&amp;gt; db
  [Profils Utilisateurs] --&amp;gt; db
  [Données Simples] --&amp;gt; db

  [Facturation (Stripe)] --&amp;gt; db
  [Facturation (Stripe)] --&amp;gt; [Stripe API]
  [Analytics Avancées] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; [SendGrid Email]
  [Webhooks Stripe] ..&amp;gt; [Stripe API] : Écoute
}

note right of &quot;Spring Boot&quot;
  **Nécessaire pour :**
  • Gestion abonnements
  • Facturation récurrente
  • Quotas dynamiques
  • Analytics complexes
  • Webhooks fiables
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Putusan&lt;/strong&gt;: Arsitektur hibrid diperlukan. Supabase untuk inti, Spring Boot untuk bagian kritis (pembayaran, penagihan).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_perdagangan_elektronik&quot;&gt;perdagangan elektronik&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;E-komers - 70% Spring Boot&quot; {
  component &quot;Storefront (JBake/React)&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Clients]
    [Catalogue Produits\n(lecture seule)]
    [Images Produits]
  }

  package &quot;Spring Boot (Inti Bisnis)&quot; #Coral {
    [Gestion Commandes]
    [Paiements Stripe]
    [Gestion Stock]
    [Calcul Frais Port]
    [Génération Factures]
    [Synchronisation ERP]
    [Emails Transactionnels]
  }

  cloud &quot;Integrasi&quot; {
    [Stripe]
    [Transporteur API]
    [ERP Externe]
  }

  database &quot;PostgreSQL&quot; as db

  frontend --&amp;gt; [Auth Clients]
  frontend --&amp;gt; [Catalogue Produits\n(lecture seule)]
  frontend --&amp;gt; [Gestion Commandes]

  [Auth Clients] --&amp;gt; db
  [Catalogue Produits\n(lecture seule)] --&amp;gt; db

  [Gestion Commandes] --&amp;gt; db
  [Paiements Stripe] --&amp;gt; [Stripe]
  [Gestion Stock] --&amp;gt; db
  [Calcul Frais Port] --&amp;gt; [Transporteur API]
  [Génération Factures] --&amp;gt; db
  [Synchronisation ERP] --&amp;gt; [ERP Externe]
  [Synchronisation ERP] --&amp;gt; db
}

note right of &quot;Spring Boot (Inti Bisnis)&quot;
  **Spring Boot indispensable :**
  • Transactions critiques
  • Orchestration complexe
  • Intégrations multiples
  • Conformité légale
  • Jobs de synchronisation
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Putusan&lt;/strong&gt;: Spring Boot penting. Supabase hanya untuk otentikasi dan katalog.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_strategi_migrasi_progresif&quot;&gt;Strategi Migrasi Progresif&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

|Semaine 1-2|
start
:Créer projet Supabase;
:Configurer Auth (Google, GitHub);
:Définir schéma PostgreSQL initial;
:Implémenter CRUD de base sur JBake;
:Déployer MVP sur GitHub Pages;
note right
  **Livrable :** Application fonctionnelle
  **Coût :** 0€
  **Temps :** 1-2 semaines
end note

|Semaine 3-4|
:Observer utilisation réelle;
:Identifier limitations;

|Décision|
if (Logique complexe\némerge ?) then (non)
  |Supabase|
  :Continuer avec Supabase seul;
  :Ajouter Edge Functions si besoin;
  stop
else (oui)
  |Spring Boot|
  :Créer projet Spring Boot;
  :Configurer validation JWT Supabase;
  :Migrer logique complexe vers Spring Boot;
  note right
    **Migration sélective**
    Seulement ce qui est complexe
  end note
endif

|Semaines suivantes|
:Déployer Spring Boot (Cloud Run, EC2);
:Connecter à PostgreSQL Supabase;
:Implémenter premiers jobs planifiés;
:Intégrer APIs tierces;

stop

note right
  **Architecture finale hybride**
  Supabase + Spring Boot
  en parfaite harmonie
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_biaya_dan_pertimbangan_operasional&quot;&gt;Biaya dan Pertimbangan Operasional&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_struktur_biaya&quot;&gt;Struktur Biaya&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Perkiraan Biaya Bulanan&quot; {

  rectangle &quot;Tahap MVP\n(0-1000 pengguna)&quot; #LightGreen {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot: N/A]
    note bottom: **Total: 0€/mois**
  }

  rectangle &quot;Fase Pertumbuhan\n(1k-10k pengguna)&quot; #LightYellow {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot (Cloud Run): 20-50€]
    [PostgreSQL (si séparé): 0-30€]
    note bottom: **Total: 20-80€/mois**
  }

  rectangle &quot;Skala Fase
(10k-100k pengguna)&quot; #LightCoral {
    [JBake (Netlify Pro): 19€]
    [Supabase Pro: 25€]
    [Spring Boot (instances multiples): 100-300€]
    [Redis Cache: 20-50€]
    [Monitoring: 20€]
    note bottom: **Total: 184-414€/mois**
  }
}

note right of &quot;Skala Fase
(10k-100k pengguna)&quot;
  À ce stade, les revenus
  justifient largement les coûts
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tanggung_jawab_operasional&quot;&gt;Tanggung jawab operasional&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Siapa yang mengelola apa?&quot; {

  rectangle &quot;Dikelola oleh Supabase (0 effort)&quot; #LightGreen {
    [Authentification]
    [Base de données]
    [Backups automatiques]
    [Scaling automatique]
    [Monitoring DB]
    [Sécurité DB]
  }

  rectangle &quot;Dikelola oleh GitHub (0 upaya)&quot; #SkyBlue {
    [Hébergement site statique]
    [HTTPS/SSL]
    [CDN global]
    [Déploiement automatique]
  }

  rectangle &quot;Mengelola (Spring Boot)&quot; #LightCoral {
    [Déploiement application]
    [Monitoring APM]
    [Logs centralisés]
    [Scaling horizontal]
    [Mises à jour sécurité]
  }
}

note bottom of &quot;Mengelola (Spring Boot)&quot;
  **Minimisable avec :**
  • Cloud Run (serverless)
  • Kubernetes (si nécessaire)
  • Services managés (RDS, etc.)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_kesimpulan_keseimbangan_sempurna&quot;&gt;Kesimpulan : Keseimbangan Sempurna&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur hibrid Supabase + Spring Boot bukanlah sebuah kompromi, ini adalah&lt;strong&gt;sinergi&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prinsip_prinsip_yang_harus_diingat&quot;&gt;Prinsip-prinsip yang Harus Diingat&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Architecture\nHybride

** Commencer Simple
***_ MVP avec Supabase
***_ 0€ de coût initial
***_ Validation rapide

** Évoluer Intelligemment
***_ Ajouter Spring Boot\nsi nécessaire
***_ Migration progressive
***_ Pas de refonte totale

** Exploiter les Forces
***_ Supabase: Simplicité
***_ Spring Boot: Puissance
***_ PostgreSQL: Source unique

** Minimiser la Complexité
***_ Pas de synchronisation
***_ Pas de duplication
***_ Architecture claire

** Optimiser les Coûts
***_ Gratuit au départ
***_ Scaling progressif
***_ ROI évident

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kapan_memilih_arsitektur_ini&quot;&gt;Kapan Memilih Arsitektur Ini?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ Arsitektur ini ideal jika :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Anda ingin memulai dengan cepat (MVP dalam hari, bukan dalam bulan)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda mengantisipasi pertumbuhan kompleksitas bisnis&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda ingin meminimalkan biaya awal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda menyukai PostgreSQL dan ingin memiliki satu sumber kebenaran tunggal.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda menyukai Kotlin dan Coroutine untuk kode bisnis&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda ingin menghindari vendor lock-in total&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ Arsitektur ini TIDAK cocok jika :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Proyek Anda sederhana dan akan tetap demikian (blog pribadi → 100% Supabase cukup)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda sudah memiliki stack backend yang sudah terbentuk yang Anda kuasai&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda lebih suka sebuah monolitik tradisional&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda membutuhkan .NET, Python, atau bahasa backend lain&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_visi_keseluruhan_final&quot;&gt;Visi Keseluruhan Final&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Arsitektur Hibrid Lengkap&quot; {

  actor &quot;Pengguna&quot; as users

  rectangle &quot;Frontend (Statik)&quot; #SkyBlue {
    [JBake / GitHub Pages]
    note right: Gratuit, CDN global
  }

  rectangle &quot;Backend Sederhana (Supabase)&quot; #LightGreen {
    [Auth OAuth2]
    [CRUD APIs]
    [Storage]
    [Realtime]
    note right
      Gratuit jusqu&#39;à 50k users
      Zéro configuration serveur
    end note
  }

  rectangle &quot;Backend Bisnis (Spring Boot)&quot; #Coral {
    [Orchestration]
    [Jobs Planifiés]
    [Intégrations]
    [Transactions]
    note right
      Activé uniquement
      si nécessaire
    end note
  }

  database &quot;PostgreSQL
Sumber unik kebenaran&quot; as db #LightGray

  users --&amp;gt; [JBake / GitHub Pages]

  [JBake / GitHub Pages] --&amp;gt; [Auth OAuth2]
  [JBake / GitHub Pages] --&amp;gt; [CRUD APIs]
  [JBake / GitHub Pages] --&amp;gt; [Storage]
  [JBake / GitHub Pages] --&amp;gt; [Realtime]
  [JBake / GitHub Pages] --&amp;gt; [Orchestration]

  [Auth OAuth2] --&amp;gt; db
  [CRUD APIs] --&amp;gt; db
  [Orchestration] --&amp;gt; db
  [Jobs Planifiés] --&amp;gt; db
  [Intégrations] --&amp;gt; db
}

note bottom of db
  **Une seule base, deux consommateurs**
  • Supabase pour le simple
  • Spring Boot pour le complexe
  • Aucune synchronisation requise
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_terbaik_dari_kedua_dunia&quot;&gt;Terbaik dari kedua dunia&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur ini memberi Anda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🚀 Kecepatan Supabase&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Memulai dalam jam, bukan minggu&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Otentikasi OAuth2 dalam beberapa klik&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;APIs REST yang dihasilkan secara otomatis&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Konfigurasi server nol&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💪 Kekuatan Spring Boot&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Kotlin dan Coroutines untuk kode asinkron yang elegan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Orkestrasi proses bisnis kompleks&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pekerjaan terencana yang andal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Transaksi ACID terjamin&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ekosistem Spring lengkap&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💰 Ekonomi Progresif&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;0€ untuk memulai dan memvalidasi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Biaya yang mengikuti pertumbuhan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Tidak ada over-engineering yang dilakukan terlalu dini&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🎯 Fleksibilitas Arsitektur&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Migrasi progresif tanpa rekonstruksi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Penambahan Spring Boot hanya jika diperlukan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Tidak ada vendor lock-in total&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Arsitektur yang dapat berevolusi&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_untuk_pergi_lebih_jauh&quot;&gt;Untuk pergi lebih jauh&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sumber_daya_teknis&quot;&gt;Sumber Daya Teknis&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Dokumentasi Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/auth&quot;&gt;Panduan Otentikasi&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/database/postgres/row-level-security&quot;&gt;Keamanan Tingkat Baris&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/api&quot;&gt;API yang dihasilkan otomatis&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Dokumentasi Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/guides/tutorials/spring-boot-kotlin/&quot;&gt;Spring Boot dengan Kotlin&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/blog/2019/04/12/going-reactive-with-spring-coroutines-and-kotlin-flow&quot;&gt;Coroutines dan Spring&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.spring.io/spring-security/reference/servlet/oauth2/resource-server/jwt.html&quot;&gt;JWT Resource Server&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Artikel Tambahan :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Keamanan API dengan JWT&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Optimasi performa PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pola migrasi progresif&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Manajemen kesalahan dalam arsitektur terdistribusi&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kasus_penggunaan_nyata&quot;&gt;Kasus penggunaan nyata&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur hibrid ini digunakan dengan sukses di :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SaaS B2B&lt;/strong&gt;: Autentikasi Supabase, penagihan Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Pasar&lt;/strong&gt;: Katalog Supabase, transaksi Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Platform konten&lt;/strong&gt;: Artikel Supabase, analitik Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Alat internal&lt;/strong&gt;: CRUD Supabase, alur kerja Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_checklist_pemulai&quot;&gt;Checklist Pemulai&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Tahap 1 - Fondasi (Minggu 1)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Buat akun Supabase - [ ] Mengonfigurasi proyek PostgreSQL - [ ] Aktifkan Auth (Google, GitHub) - [ ] Menentukan skema awal - [ ] Mengatur Row Level Security - [ ] Menguji API dari JBake&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Phase 2 - MVP (Minggu 2-3)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Mengimplementasikan halaman utama - [ ] Mengintegrasikan otentikasi OAuth2 - [ ] Buat formulir CRUD - [ ] Mengatur Penyimpanan untuk file - [ ] Men-deploy ke GitHub Pages - [ ] Uji dalam kondisi nyata&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Fase 3 - evolusi (sesuai kebutuhan)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Identifikasi kebutuhan logika kompleks - [ ] Membuat proyek Spring Boot jika diperlukan - [ ] Konfigurasi validasi JWT Supabase - [ ] Menghubungkan ke PostgreSQL Supabase - [ ] Memigrasikan fitur-fitur kompleks - [ ] Menerapkan pekerjaan terjadwal - [ ] Men-deploy Spring Boot (Cloud Run, dst.)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_anti_patterns_yang_harus_dihindari&quot;&gt;Anti-Patterns yang harus dihindari&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ Jangan lakukan :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Duplikasi data antara Supabase dan Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Buat dua basis data PostgreSQL terpisah&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Mengodek otentikasi sendiri&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Menggunakan Spring Boot untuk CRUD sederhana&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Menglebih-lebihan arsitektur sejak awal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Mengabaikan keamanan tingkat baris Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ Lebih baik :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Membagikan satu basis data PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Biarkan Supabase mengelola autentikasi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Menggunakan Spring Boot hanya untuk kompleksitas&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Mulai sederhana, berkembang secara bertahap&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Manfaatkan kekuatan setiap teknologi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Mengamankan dengan RLS pada tingkat basis data&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_prospek_evolusi&quot;&gt;Prospek Evolusi&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_penambahan_kemampuan_baru&quot;&gt;Penambahan Kemampuan Baru&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Arsitektur Saat Ini&quot; #SkyBlue {
  [JBake]
  [Supabase]
  [Spring Boot]
}

rectangle &quot;Evolusi yang Mungkin&quot; #LightYellow {

  package &quot;Kinerja&quot; {
    [Redis Cache]
    [CDN pour Assets]
    [PostgreSQL Replicas]
  }

  package &quot;Pemantauan&quot; {
    [Grafana]
    [Prometheus]
    [Sentry]
  }

  package &quot;CI/CD&quot; {
    [GitHub Actions]
    [Tests Automatisés]
    [Déploiement Continu]
  }

  package &quot;Fitur&quot; {
    [Search (ElasticSearch)]
    [Queue (RabbitMQ)]
    [Event Sourcing]
  }
}

[Spring Boot] .down.&amp;gt; [Redis Cache] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Queue (RabbitMQ)] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Search (ElasticSearch)] : Peut ajouter

[Supabase] .down.&amp;gt; [PostgreSQL Replicas] : Peut ajouter

note bottom
  **Architecture extensible**
  Chaque ajout est indépendant
  Pas de refonte globale nécessaire
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_penskalaan_horizontal&quot;&gt;Penskalaan Horizontal&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ketika aplikasi Anda tumbuh, arsitektur hybrid diskalakan secara alami :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Skala otomatis hingga jutaan operasi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Replikasi baca untuk performa baca&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pemulihan poin waktu untuk keamanan&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;beberapa instance di belakang load balancer&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Desain stateless memfasilitasi skala horizontal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kubernetes untuk orkestrasi jika diperlukan&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;PostgreSQL :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Partitioning untuk tabel yang berukuran besar&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;pooling koneksi (PgBouncer)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sharding memang diperlukan (jarang)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_saksi_saksi_arkitektonik&quot;&gt;Saksi-saksi Arkitektonik&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_startup_saas_50k_pengguna&quot;&gt;Startup SaaS (50k pengguna)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&amp;lt;/think&amp;gt; Kami memulai dengan 100% Supabase. Pada 5.000 pengguna, kami menambahkan Spring Boot hanya untuk penagihan Stripe dan laporan bulanan. Satu tahun kemudian, 80% dari operasi kami masih melewati Supabase. Spring Boot hanya mengelola bagian kritis. Pemisahan ini memungkinkan kami untuk menskalakan tanpa rekonstruksi. &lt;em&gt;__&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_platform_e_learning_10k_pengguna&quot;&gt;Platform e-learning (10k pengguna)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Autentikasi OAuth2 Supabase telah menghemat tiga minggu pengembangan kami. API yang dihasilkan secara otomatis mengelola seluruh katalog kursus kami. Spring Boot hanya digunakan untuk sertifikat PDF dan email progres. Arsitektur sederhana, mudah dipelihara, dan dapat diskalakan. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_pasar_b2b_3k_pengguna&quot;&gt;Pasar B2B (3k pengguna)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Spring Boot mengelola transaksi antara pembeli dan penjual (krusial). Supabase mengelola semua yang lain: profil, pesan realtime, dokumen. Faktanya mereka berbagi basis data PostgreSQL yang sama menghindarkan kita dari sinkronisasi kompleks. Pilihan arsitektur terbaik yang pernah kita buat. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sintesis_paradigma_arsitektur_modern&quot;&gt;Sintesis: Paradigma Arsitektur Modern&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur hibrid Supabase + Spring Boot merupakan paradigma baru:&lt;strong&gt;spesialisasi arsitektur&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Paradigma Lama&quot; #LightCoral {
  card &quot;Semua di Backend&quot; {
    [Auth]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [Storage]
    [Realtime]
  }
  note bottom
    Complexité maximale
    dès le jour 1
  end note
}

rectangle &quot;Paradigma Baru&quot; #LightGreen {
  card &quot;Supabase
(kemudahan)&quot; {
    [Auth]
    [CRUD Simple]
    [Storage]
    [Realtime]
  }

  card &quot;Spring Boot
(Diferensiasi)&quot; {
    [Logique Métier]
    [Jobs]
    [Intégrations]
  }

  note bottom
    Complexité progressive
    ajoutée seulement si nécessaire
  end note
}

[Ancien Paradigme] -right-&amp;gt; [Nouveau Paradigme] : Évolution

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Prinsip dasar:&lt;/strong&gt;Jangan membangun hal-hal yang sudah ada dalam bentuk layanan. Fokuslah pada yang membedakan aplikasi Anda.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_aturan_8020&quot;&gt;Aturan 80/20&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Di sebagian besar aplikasi:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;80% operasi&lt;/strong&gt;adalah CRUD standar → Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;20% dari operasi&lt;/strong&gt;memerlukan logika bisnis → Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Aturan alami ini membenarkan arsitektur hibrida.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Distribusi Operasi&quot; {

  rectangle &quot;80% - Operasi Standar&quot; #LightGreen {
    [Lecture de données]
    [Création d&#39;entités]
    [Mise à jour simple]
    [Suppression]
    [Upload fichiers]
    [Authentification]

    note bottom: **Géré par Supabase**
  }

  rectangle &quot;20% - Logika bisnis&quot; #Coral {
    [Calculs complexes]
    [Workflows multi-étapes]
    [Transactions critiques]
    [Intégrations tierces]
    [Jobs planifiés]

    note bottom: **Géré par Spring Boot**
  }
}

note right
  **Focus optimal :**
  Votre temps de développement
  concentré sur les 20% qui
  différencient votre produit
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_kesimpulan_akhir&quot;&gt;Kesimpulan Akhir&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur hibrid bukanlah kompromi teknis, ini adalah&lt;strong&gt;keputusan strategis&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Ini memungkinkan Anda:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✅ Mulai cepat dengan MVP yang berfungsi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Memvalidasi pasar Anda tanpa investasi berat&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Bertahap berkembang ketika kompleksitas menuntutnya&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Mengendalikan biaya Anda pada setiap tahap&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Memanfaatkan yang terbaik dari setiap teknologi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Menghindari over-engineering yang terlalu dini&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Pertahankan fleksibilitas untuk masa depan&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Dia mewakili :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;🎯&lt;strong&gt;Pragmatisme&lt;/strong&gt;: Setiap teknologi di mana dia unggul&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🚀&lt;strong&gt;kecepatan&lt;/strong&gt;: Waktu untuk pasar minimal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;💰&lt;strong&gt;Ekonomi&lt;/strong&gt;: Biaya yang selaras dengan nilai&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🔮&lt;strong&gt;Skalabilitas&lt;/strong&gt;: Arsitektur yang tumbuh bersama Anda&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🛡️&lt;strong&gt;Ketahanan&lt;/strong&gt;Servis yang terbukti dan andal&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_langkah_selanjutnya_anda&quot;&gt;Langkah Selanjutnya Anda&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Jika Anda menyukai arsitektur ini, berikut ini cara memulai:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Buat akun Supabase&lt;/strong&gt;(gratis)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Tentukan skema data minimal Anda&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Konfigurasikan autentikasi OAuth2&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Buat halaman pertama JBake Anda yang menggunakan API&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Terapkan di GitHub Pages&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Anda akan memiliki MVP yang fungsional di&lt;strong&gt;beberapa hari&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Spring Boot akan datang secara alami saat Anda membutuhkannya. Belum sebelumnya.&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Arsitektur hibrid adalah seni membangun tepat apa yang diperlukan, pada saat yang tepat.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;Semoga berkembang dengan baik! 🚀&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;Bagikan artikel ini jika Anda berpikir bahwa ia dapat membantu pengembang lain untuk membuat pilihan arsitektur yang tepat.&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;waktu membaca : 12 minutes&lt;/div&gt;
&lt;p&gt;Alih-alih memilih antara kesederhanaan Supabase dan kekuatan Spring Boot, mengapa tidak menggabungkan keduanya? Temukan arsitektur hibrida yang memanfaatkan yang terbaik dari setiap teknologi.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;tok&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_dilema_palsu_arsitektur_modern&quot;&gt;Dilema Palsu Arsitektur Modern&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Saat membangun aplikasi modern dengan frontend statis, kita sering kali menghadapi pilihan biner:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Menaruh semua harapan pada solusi Backend-as-a-Service&lt;/strong&gt;(Supabase, Firebase) - sederhana tetapi terbatas&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Membangun backend lengkap&lt;/strong&gt;(Spring Boot, Node.js) - kuat namun kompleks&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Pilihan ini adalah dilema palsu. Arsitektur hibrid menawarkan jalan ketiga: &lt;strong&gt;menggunakan setiap teknologi tempat ia mengungguli&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_visi_arsitektur&quot;&gt;Visi Arsitektur&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_arsitektur_tradisional_monolitik&quot;&gt;Arsitektur Tradisional: Monolitik&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Arsitektur Tradisional&quot; {
  actor Utilisateur as user
  component &quot;frontend&quot; as frontend #LightBlue
  component &quot;backend monolitik&quot; as backend #LightCoral {
    [Authentification]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [APIs Tierces]
  }
  database &quot;Basis data&quot; as db #LightGray

  user --&amp;gt; frontend
  frontend --&amp;gt; backend : Toutes les requêtes
  backend --&amp;gt; db
}

note right of backend
  Tout passe par le backend
  même les opérations simples

  ⚠️ Point de congestion unique
  ⚠️ Complexité dès le départ
  ⚠️ Couplage fort
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Pendekatan ini, bahkan operasi paling sederhana (membaca artikel, membuat komentar) harus melalui backend Anda. Anda membayar biaya kompleksitas sejak hari pertama.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_arsitektur_baas_semua_delegasi&quot;&gt;Arsitektur BaaS: Semua Delegasi&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Arsitektur BaaS Murni&quot; {
  actor Utilisateur as user
  component &quot;Frontend&quot; as frontend #LightBlue
  cloud &quot;Supabase / Firebase&quot; as baas #LightGreen {
    [Auth]
    [Database]
    [Storage]
    [Edge Functions]
  }

  user --&amp;gt; frontend
  frontend --&amp;gt; baas : Toutes les opérations
}

note right of baas
  Développement rapide
  Pas de serveur à gérer

  ⚠️ Limité pour logique complexe
  ⚠️ Vendor lock-in
  ⚠️ Edge Functions contraintes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sebaliknya, mendelegasikan semuanya ke BaaS menarik di awal tetapi menunjukkan batasnya dengan cepat saat logika bisnis menjadi kompleks.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_arsitektur_hibrid_pemisahan_tanggung_jawab&quot;&gt;Arsitektur Hibrid: Pemisahan Tanggung Jawab&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Utilisateur as user #LightBlue

package &quot;Lapisan Frontend&quot; {
  component &quot;Situs Statis JBake&quot; as frontend #SkyBlue
}

package &quot;Lapisan Sederhana (Supabase)&quot; #LightGreen {
  component &quot;Otentikasi&quot; as auth
  component &quot;CRUD Dasar&quot; as crud
  component &quot;Penyimpanan File&quot; as storage
  component &quot;Waktu nyata&quot; as realtime
}

package &quot;Lapisan Bisnis (Spring Boot)&quot; #Coral {
  component &quot;Logika Kompleks&quot; as logic
  component &quot;Orkestrasi&quot; as orchestration
  component &quot;Jobs Jadwal&quot; as jobs
  component &quot;Integrasi&quot; as integrations
}

database &quot;PostgreSQL yang dibagikan&quot; as db #LightGray

user --&amp;gt; frontend

frontend --&amp;gt; auth : OAuth2, JWT
frontend --&amp;gt; crud : Articles, Profils
frontend --&amp;gt; storage : Images, Fichiers
frontend --&amp;gt; realtime : Notifications

frontend --&amp;gt; logic : Calculs, Rapports
frontend --&amp;gt; orchestration : Workflows
logic --&amp;gt; integrations : Stripe, APIs
orchestration --&amp;gt; db
jobs --&amp;gt; db

crud --&amp;gt; db
auth --&amp;gt; db

note bottom of db
  **Une seule source de vérité**
  Partagée entre Supabase et Spring Boot
end note

note right of auth
  **Gratuit jusqu&#39;à 50k users**
  Configuration en quelques clics
  OAuth2 multi-providers
end note

note right of logic
  **Activé seulement si nécessaire**
  Kotlin + Coroutines
  Transactions complexes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur hybrida memisahkan dengan jelas tanggung jawab berdasarkan kompleksitas dan sifat operasi.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_prinsip_desain&quot;&gt;Prinsip Desain&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prinsip_1_mulai_sederhana_berkembang_cerdas&quot;&gt;Prinsip 1 : Mulai Sederhana, Berkembang Cerdas&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Tahap 1 : MVP&quot; #LightGreen {
  component &quot;JBake + Supabase&quot; as mvp
  note right
    ✓ Développement en jours
    ✓ Coût : 0€
    ✓ Validation concept
  end note
}

rectangle &quot;**Tahap 2 : Pertumbuhan**&quot; #LightYellow {
  component &quot;JBake + Supabase
+ Spring Boot (opsional)&quot; as growth
  note right
    ✓ Logique métier émerge
    ✓ Premiers jobs planifiés
    ✓ Intégrations tierces
  end note
}

rectangle &quot;Tahap 3: Skala&quot; #LightCoral {
  component &quot;Arsitektur Lengkap&quot; as scale
  note right
    ✓ Orchestration complexe
    ✓ Performances optimisées
    ✓ Cache distribué
  end note
}

mvp -down-&amp;gt; growth : Quand la complexité\nle justifie
growth -down-&amp;gt; scale : Optimisation\ncontinue
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Jangan membangun Spring Boot jika Anda tidak membutuhkannya.&lt;/strong&gt;Mulai dengan Supabase, tambahkan Spring Boot bila kompleksitas membenarkannya.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prinsip_2_pemisahan_berdasarkan_jenis_operasi&quot;&gt;Prinsip 2 : Pemisahan berdasarkan Jenis Operasi&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Opérations\nApplicatives

left side

** Opérations Simples\n(Supabase)
***_ CRUD Standard
****_ Lecture
****_ Création
****_ Mise à jour
****_ Suppression
***_ Authentification
****_ Login/Logout
****_ OAuth2
****_ Gestion session
***_ Stockage
****_ Upload fichiers
****_ CDN automatique
***_ Temps Réel
****_ WebSocket
****_ Notifications

right side

** Opérations Complexes\n(Spring Boot)
***_ Logique Métier
****_ Calculs complexes
****_ Règles métier
****_ Validations avancées
***_ Orchestration
****_ Multi-services
****_ Transactions distribuées
****_ Saga patterns
***_ Tâches Planifiées
****_ Rapports périodiques
****_ Synchronisations
****_ Nettoyages
***_ Intégrations
****_ Paiements (Stripe)
****_ APIs tierces
****_ Services ML/AI

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prinsip_3_satu_sumber_kebenaran&quot;&gt;Prinsip 3 : Satu Sumber Kebenaran&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

database &quot;PostgreSQL&quot; as db #LightGray {
  package &quot;skema: auth (Supabase)&quot; #LightGreen {
    [users]
    [sessions]
    [identities]
  }

  package &quot;Skema: publik (dibagikan)&quot; #SkyBlue {
    [articles]
    [comments]
    [profiles]
  }

  package &quot;Skema: bisnis (Spring Boot)&quot; #Coral {
    [orders]
    [payments]
    [reports]
  }
}

component &quot;Supabase&quot; as supabase #LightGreen
component &quot;Spring Boot&quot; as spring #Coral

supabase -down-&amp;gt; users : Gère
supabase -down-&amp;gt; sessions : Gère
supabase -down-&amp;gt; articles : Accède
supabase -down-&amp;gt; comments : Accède
supabase -down-&amp;gt; profiles : Accède

spring -down-&amp;gt; articles : Accède
spring -down-&amp;gt; profiles : Accède
spring -down-&amp;gt; orders : Gère
spring -down-&amp;gt; payments : Gère
spring -down-&amp;gt; reports : Gère

note right of db
  **Avantages :**
  • Pas de synchronisation complexe
  • JOINs possibles entre tables
  • Cohérence garantie
  • Migrations unifiées
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dengan berbagi instance PostgreSQL yang sama, Supabase dan Spring Boot bekerja pada data yang sama tanpa sinkronisasi yang kompleks.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_orkestrasi_aliran&quot;&gt;Orkestrasi Aliran&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_alur_1_otentikasi_terpusat&quot;&gt;Alur 1 : Otentikasi Terpusat&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;Pengguna&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Supabase Auth&quot; as auth
participant &quot;Spring Boot&quot; as spring
database &quot;PostgreSQL&quot; as db

== Authentification ==
user -&amp;gt; jbake : Clique &quot;Masuk&quot;
jbake -&amp;gt; auth : Redirect OAuth2 (Google/GitHub)
auth -&amp;gt; user : Consent screen
user -&amp;gt; auth : Autorise
auth -&amp;gt; auth : Génère JWT
auth -&amp;gt; jbake : Retourne JWT + Refresh Token
jbake -&amp;gt; jbake : Stocke tokens (sessionStorage)

== Accès aux Ressources ==
group Opération Simple (CRUD)
  user -&amp;gt; jbake : Crée un article
  jbake -&amp;gt; db : POST avec JWT
  note right: Supabase Row Level Security\nvérifie le JWT automatiquement
  db -&amp;gt; jbake : Article créé
end

group Opération Complexe (Métier)
  user -&amp;gt; jbake : Génère un rapport
  jbake -&amp;gt; spring : POST /api/reports\navec JWT
  spring -&amp;gt; spring : Valide JWT Supabase
  spring -&amp;gt; spring : Extrait claims (user_id, roles)
  spring -&amp;gt; db : Requêtes complexes
  spring -&amp;gt; jbake : Rapport généré
end

note over auth, spring
  **Le JWT est universel**
  Valide par Supabase ET Spring Boot
  Pas de double authentification
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Poin penting&lt;/strong&gt;: Sebuah proses otentikasi tunggal, satu JWT, dapat digunakan di mana saja.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_aliran_2_orkeshtrasi_sebuah_proses_bisnis_kompleks&quot;&gt;Aliran 2 : Orkeshtrasi sebuah Proses Bisnis Kompleks&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;Klien&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Spring Boot&quot; as spring
participant &quot;Supabase DB&quot; as supadb
participant &quot;Stripe API&quot; as stripe
participant &quot;layanan persediaan&quot; as inventory
participant &quot;Layanan Email&quot; as email
database &quot;PostgreSQL&quot; as db

user -&amp;gt; jbake : Passe commande
jbake -&amp;gt; spring : POST /api/orders/create

== Orchestration Spring Boot ==
spring -&amp;gt; db : BEGIN TRANSACTION

par Vérifications Parallèles
  spring -&amp;gt; inventory : Vérifier stock
  inventory -&amp;gt; spring : Stock OK
else
  spring -&amp;gt; db : Vérifier profil client
  db -&amp;gt; spring : Client vérifié
end

spring -&amp;gt; stripe : Créer Payment Intent
stripe -&amp;gt; spring : Intent créé (ID: pi_xxx)

spring -&amp;gt; db : Créer Order (status: PENDING)
db -&amp;gt; spring : Order créé

spring -&amp;gt; stripe : Confirmer paiement
stripe -&amp;gt; spring : Paiement confirmé

spring -&amp;gt; db : Update Order (status: PAID)
spring -&amp;gt; inventory : Décrémenter stock
spring -&amp;gt; db : COMMIT TRANSACTION

par Notifications Asynchrones
  spring -&amp;gt; email : Email confirmation
else
  spring -&amp;gt; supadb : Insert notification
  note right: Notification temps réel\nvia Supabase Realtime
end

spring -&amp;gt; jbake : Order confirmé
jbake -&amp;gt; user : Affiche confirmation

note over spring
  **Responsabilités Spring Boot :**
  • Transaction ACID
  • Orchestration multi-services
  • Rollback automatique si erreur
  • Gestion des cas limites
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Apa yang diberikan Spring Boot&lt;/strong&gt;Orchestrasi yang andal dari proses kompleks yang melibatkan beberapa sistem dengan jaminan transaksional.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_aliran_3_pekerjaan_terjadwal_dan_sinkronisasi&quot;&gt;Aliran 3: Pekerjaan terjadwal dan sinkronisasi&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

participant &quot;Penjadwal
(Spring Boot)&quot; as scheduler
participant &quot;layanan pelaporan
layanan pelaporan&quot; as report
participant &quot;PostgreSQL&quot; as db
participant &quot;API eksternal&quot; as api
participant &quot;Layanan Email&quot; as email
participant &quot;Supabase Storage&quot; as storage

== Job Quotidien : 2h00 ==
activate scheduler
scheduler -&amp;gt; report : Déclenche génération rapport

activate report
report -&amp;gt; db : Récupère données\ndes dernières 24h
db -&amp;gt; report : Dataset

report -&amp;gt; report : Calculs &amp;amp; Agrégations
report -&amp;gt; report : Génération PDF

report -&amp;gt; storage : Upload PDF
storage -&amp;gt; report : URL publique

report -&amp;gt; email : Envoie aux admins\navec lien PDF
deactivate report

== Job Hebdomadaire : Dimanche 3h00 ==
scheduler -&amp;gt; report : Synchronisation externe

activate report
report -&amp;gt; api : Fetch données externes
api -&amp;gt; report : Nouvelles données

report -&amp;gt; db : Mise à jour tables
report -&amp;gt; db : Nettoyage données obsolètes
deactivate report

== Job Mensuel : 1er du mois ==
scheduler -&amp;gt; report : Facturation

activate report
report -&amp;gt; db : Liste clients actifs
report -&amp;gt; report : Calcul montants
report -&amp;gt; api : Génération factures (Stripe)
report -&amp;gt; email : Envoi factures
deactivate report

deactivate scheduler

note right of scheduler
  **Impossible avec Supabase seul**
  Edge Functions non adaptées
  pour jobs longs et récurrents
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Apa yang Spring Boot bawa&lt;/strong&gt; : Pekerjaan terjadwal yang andal dengan pengelolaan status, retry otomatis, dan eksekusi terjamin.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_matriks_keputusan&quot;&gt;Matriks Keputusan&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kapan_menggunakan_supabase&quot;&gt;Kapan menggunakan Supabase?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité à implémenter;

if (CRUD simple ?) then (oui)
  :✅ **Supabase**;
  stop
else (non)
  if (Authentification ?) then (oui)
    :✅ **Supabase Auth**;
    stop
  else (non)
    if (Upload fichiers ?) then (oui)
      :✅ **Supabase Storage**;
      stop
    else (non)
      if (Temps réel ?) then (oui)
        :✅ **Supabase Realtime**;
        stop
      else (non)
        if (Row Level Security\nsuffisante ?) then (oui)
          :✅ **Supabase + Policies**;
          stop
        else (non)
          :⚠️ **Considérer Spring Boot**;
          #Coral:Passer à l&#39;arbre\nde décision Spring Boot;
          stop
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kapan_menggunakan_spring_boot&quot;&gt;Kapan Menggunakan Spring Boot ?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité complexe;

if (Orchestration\nmulti-services ?) then (oui)
  :✅ **Spring Boot**;
  stop
else (non)
  if (Transaction ACID\ncritique ?) then (oui)
    :✅ **Spring Boot**;
    stop
  else (non)
    if (Job planifié ?) then (oui)
      :✅ **Spring Boot Scheduler**;
      stop
    else (non)
      if (Intégration API\ntierce complexe ?) then (oui)
        :✅ **Spring Boot**;
        stop
      else (non)
        if (Calculs lourds\n&amp;gt; 10 secondes ?) then (oui)
          :✅ **Spring Boot**;
          stop
        else (non)
          if (Cache distribué\nnécessaire ?) then (oui)
            :✅ **Spring Boot + Redis**;
            stop
          else (non)
            :⚠️ **Probablement Supabase**;
            #LightGreen:Revenir à l&#39;arbre\nde décision Supabase;
            stop
          endif
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_contoh_arsitektur_per_tipe_proyek&quot;&gt;Contoh Arsitektur per Tipe Proyek&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_blog_portofolio&quot;&gt;Blog / Portofolio&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Blog Pribadi - 95% Supabase&quot; {
  component &quot;JBake&quot; as jbake #SkyBlue

  package &quot;Supabase (Gratis)&quot; #LightGreen {
    [Auth: OAuth2 Google]
    [Articles (CRUD)]
    [Commentaires]
    [Images (Storage)]
    [Notifications Realtime]
  }

  package &quot;Spring Boot (Opsional)&quot; #LightCoral {
    [Newsletter Mensuelle]
    note bottom: Job planifié uniquement
  }

  database &quot;PostgreSQL&quot; as db

  jbake --&amp;gt; [Auth: OAuth2 Google]
  jbake --&amp;gt; [Articles (CRUD)]
  jbake --&amp;gt; [Commentaires]
  jbake --&amp;gt; [Images (Storage)]
  jbake --&amp;gt; [Notifications Realtime]

  [Articles (CRUD)] --&amp;gt; db
  [Commentaires] --&amp;gt; db
  [Newsletter Mensuelle] --&amp;gt; db
}

note bottom of &quot;Spring Boot (Opsional)&quot;
  **Spring Boot pas obligatoire**
  Newsletter peut être gérée
  par un service tiers (Mailchimp)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;putusan&lt;/strong&gt;: 100% Supabase sudah cukup.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_aplikasi_saas&quot;&gt;Aplikasi SaaS&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Aplikasi SaaS - Arsitektur Hibrid&quot; {
  component &quot;JBake / React&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Multi-tenant]
    [Profils Utilisateurs]
    [Données Simples]
    [Storage Documents]
  }

  package &quot;Spring Boot&quot; #Coral {
    [Facturation (Stripe)]
    [Analytics Avancées]
    [Rapports Mensuels]
    [Quotas &amp;amp; Limites]
    [Webhooks Stripe]
  }

  cloud &quot;Layanan Eksternal&quot; {
    [Stripe API]
    [SendGrid Email]
  }

  database &quot;PostgreSQL Dibagikan&quot; as db

  frontend --&amp;gt; [Auth Multi-tenant]
  frontend --&amp;gt; [Profils Utilisateurs]
  frontend --&amp;gt; [Données Simples]
  frontend --&amp;gt; [Facturation (Stripe)]
  frontend --&amp;gt; [Analytics Avancées]

  [Auth Multi-tenant] --&amp;gt; db
  [Profils Utilisateurs] --&amp;gt; db
  [Données Simples] --&amp;gt; db

  [Facturation (Stripe)] --&amp;gt; db
  [Facturation (Stripe)] --&amp;gt; [Stripe API]
  [Analytics Avancées] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; [SendGrid Email]
  [Webhooks Stripe] ..&amp;gt; [Stripe API] : Écoute
}

note right of &quot;Spring Boot&quot;
  **Nécessaire pour :**
  • Gestion abonnements
  • Facturation récurrente
  • Quotas dynamiques
  • Analytics complexes
  • Webhooks fiables
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;putusan&lt;/strong&gt;Arsitektur hibrid diperlukan. Supabase untuk bagian inti, Spring Boot untuk bagian kritis (pembayaran, penagihan).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_perdagangan_elektronik&quot;&gt;perdagangan elektronik&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;E-niaga - 70% Spring Boot&quot; {
  component &quot;Storefront (JBake/React)&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Clients]
    [Catalogue Produits\n(lecture seule)]
    [Images Produits]
  }

  package &quot;Spring Boot (Inti Bisnis)&quot; #Coral {
    [Gestion Commandes]
    [Paiements Stripe]
    [Gestion Stock]
    [Calcul Frais Port]
    [Génération Factures]
    [Synchronisation ERP]
    [Emails Transactionnels]
  }

  cloud &quot;Integrasi&quot; {
    [Stripe]
    [Transporteur API]
    [ERP Externe]
  }

  database &quot;PostgreSQL&quot; as db

  frontend --&amp;gt; [Auth Clients]
  frontend --&amp;gt; [Catalogue Produits\n(lecture seule)]
  frontend --&amp;gt; [Gestion Commandes]

  [Auth Clients] --&amp;gt; db
  [Catalogue Produits\n(lecture seule)] --&amp;gt; db

  [Gestion Commandes] --&amp;gt; db
  [Paiements Stripe] --&amp;gt; [Stripe]
  [Gestion Stock] --&amp;gt; db
  [Calcul Frais Port] --&amp;gt; [Transporteur API]
  [Génération Factures] --&amp;gt; db
  [Synchronisation ERP] --&amp;gt; [ERP Externe]
  [Synchronisation ERP] --&amp;gt; db
}

note right of &quot;Spring Boot (Inti Bisnis)&quot;
  **Spring Boot indispensable :**
  • Transactions critiques
  • Orchestration complexe
  • Intégrations multiples
  • Conformité légale
  • Jobs de synchronisation
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Putusan&lt;/strong&gt;Spring Boot diperlukan. Supabase hanya untuk auth dan katalog.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_strategi_migrasi_bertahap&quot;&gt;Strategi migrasi bertahap&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

|Semaine 1-2|
start
:Créer projet Supabase;
:Configurer Auth (Google, GitHub);
:Définir schéma PostgreSQL initial;
:Implémenter CRUD de base sur JBake;
:Déployer MVP sur GitHub Pages;
note right
  **Livrable :** Application fonctionnelle
  **Coût :** 0€
  **Temps :** 1-2 semaines
end note

|Semaine 3-4|
:Observer utilisation réelle;
:Identifier limitations;

|Décision|
if (Logique complexe\némerge ?) then (non)
  |Supabase|
  :Continuer avec Supabase seul;
  :Ajouter Edge Functions si besoin;
  stop
else (oui)
  |Spring Boot|
  :Créer projet Spring Boot;
  :Configurer validation JWT Supabase;
  :Migrer logique complexe vers Spring Boot;
  note right
    **Migration sélective**
    Seulement ce qui est complexe
  end note
endif

|Semaines suivantes|
:Déployer Spring Boot (Cloud Run, EC2);
:Connecter à PostgreSQL Supabase;
:Implémenter premiers jobs planifiés;
:Intégrer APIs tierces;

stop

note right
  **Architecture finale hybride**
  Supabase + Spring Boot
  en parfaite harmonie
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_biaya_dan_pertimbangan_operasional&quot;&gt;Biaya dan Pertimbangan Operasional&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_struktur_biaya&quot;&gt;Struktur Biaya&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Perkiraan Biaya Bulanan&quot; {

  rectangle &quot;Tahap MVP\n(0-1000 pengguna)&quot; #LightGreen {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot: N/A]
    note bottom: **Total: 0€/mois**
  }

  rectangle &quot;Fase Pertumbuhan\n(1k-10k users)&quot; #LightYellow {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot (Cloud Run): 20-50€]
    [PostgreSQL (si séparé): 0-30€]
    note bottom: **Total: 20-80€/mois**
  }

  rectangle &quot;Skala Fase
(10k-100k pengguna)&quot; #LightCoral {
    [JBake (Netlify Pro): 19€]
    [Supabase Pro: 25€]
    [Spring Boot (instances multiples): 100-300€]
    [Redis Cache: 20-50€]
    [Monitoring: 20€]
    note bottom: **Total: 184-414€/mois**
  }
}

note right of &quot;Skala Fase
(10k-100k pengguna)&quot;
  À ce stade, les revenus
  justifient largement les coûts
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tanggung_jawab_operasional&quot;&gt;Tanggung Jawab Operasional&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Siapa yang mengelola apa?&quot; {

  rectangle &quot;Dikelola oleh Supabase (0 upaya)&quot; #LightGreen {
    [Authentification]
    [Base de données]
    [Backups automatiques]
    [Scaling automatique]
    [Monitoring DB]
    [Sécurité DB]
  }

  rectangle &quot;Dikelola oleh GitHub (0 upaya)&quot; #SkyBlue {
    [Hébergement site statique]
    [HTTPS/SSL]
    [CDN global]
    [Déploiement automatique]
  }

  rectangle &quot;Untuk Mengelola (Spring Boot)&quot; #LightCoral {
    [Déploiement application]
    [Monitoring APM]
    [Logs centralisés]
    [Scaling horizontal]
    [Mises à jour sécurité]
  }
}

note bottom of &quot;Untuk Mengelola (Spring Boot)&quot;
  **Minimisable avec :**
  • Cloud Run (serverless)
  • Kubernetes (si nécessaire)
  • Services managés (RDS, etc.)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_kesimpulan_keseimbangan_sempurna&quot;&gt;Kesimpulan: Keseimbangan Sempurna&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur hibrid Supabase + Spring Boot bukanlah sebuah kompromi, ini adalah&lt;strong&gt;sinergi&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prinsip_prinsip_yang_harus_diingat&quot;&gt;Prinsip-prinsip yang harus diingat&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Architecture\nHybride

** Commencer Simple
***_ MVP avec Supabase
***_ 0€ de coût initial
***_ Validation rapide

** Évoluer Intelligemment
***_ Ajouter Spring Boot\nsi nécessaire
***_ Migration progressive
***_ Pas de refonte totale

** Exploiter les Forces
***_ Supabase: Simplicité
***_ Spring Boot: Puissance
***_ PostgreSQL: Source unique

** Minimiser la Complexité
***_ Pas de synchronisation
***_ Pas de duplication
***_ Architecture claire

** Optimiser les Coûts
***_ Gratuit au départ
***_ Scaling progressif
***_ ROI évident

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kapan_memilih_arsitektur_ini&quot;&gt;Kapan Memilih Arsitektur Ini?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ Arsitektur ini ideal jika :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Anda ingin memulai dengan cepat (MVP dalam hari, bukan dalam bulan)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kamu mengantisipasi pertumbuhan kompleksitas bisnis&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda ingin meminimalkan biaya awal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda menyukai PostgreSQL dan ingin memiliki satu sumber kebenaran yang unik&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda menyukai Kotlin dan coroutine untuk kode bisnis&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda ingin menghindari vendor lock-in total&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ Arsitektur ini TIDAK cocok jika :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Proyek Anda sederhana dan akan tetap sederhana (blog pribadi → 100% Supabase cukup)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda sudah memiliki sebuah stack backend yang ter-establish yang Anda menguasai&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda lebih suka sebuah monolit tradisional&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Anda membutuhkan .NET, Python, atau bahasa pemrograman lain di sisi backend&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_visions_keseluruhan_akhir&quot;&gt;Visions Keseluruhan Akhir&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Arsitektur Hibrid Lengkap&quot; {

  actor &quot;Pengguna&quot; as users

  rectangle &quot;frontend (statis)&quot; #SkyBlue {
    [JBake / GitHub Pages]
    note right: Gratuit, CDN global
  }

  rectangle &quot;Backend sederhana (Supabase)&quot; #LightGreen {
    [Auth OAuth2]
    [CRUD APIs]
    [Storage]
    [Realtime]
    note right
      Gratuit jusqu&#39;à 50k users
      Zéro configuration serveur
    end note
  }

  rectangle &quot;Backend Bisnis (Spring Boot)&quot; #Coral {
    [Orchestration]
    [Jobs Planifiés]
    [Intégrations]
    [Transactions]
    note right
      Activé uniquement
      si nécessaire
    end note
  }

  database &quot;PostgreSQL\nSumber Tunggal Kebenaran&quot; as db #LightGray

  users --&amp;gt; [JBake / GitHub Pages]

  [JBake / GitHub Pages] --&amp;gt; [Auth OAuth2]
  [JBake / GitHub Pages] --&amp;gt; [CRUD APIs]
  [JBake / GitHub Pages] --&amp;gt; [Storage]
  [JBake / GitHub Pages] --&amp;gt; [Realtime]
  [JBake / GitHub Pages] --&amp;gt; [Orchestration]

  [Auth OAuth2] --&amp;gt; db
  [CRUD APIs] --&amp;gt; db
  [Orchestration] --&amp;gt; db
  [Jobs Planifiés] --&amp;gt; db
  [Intégrations] --&amp;gt; db
}

note bottom of db
  **Une seule base, deux consommateurs**
  • Supabase pour le simple
  • Spring Boot pour le complexe
  • Aucune synchronisation requise
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_terbaik_dari_kedua_dunia&quot;&gt;Terbaik dari kedua dunia&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur ini memberi Anda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🚀 Kecepatan Supabase&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Mulai dalam jam, bukan dalam minggu&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Autentikasi OAuth2 dalam beberapa klik&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;APIs REST yang dihasilkan secara otomatis&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Konfigurasi server nol&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💪 Kekuatan Spring Boot&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Kotlin dan Coroutines untuk kode asinkron yang elegan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Orkestrasi proses bisnis kompleks&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pekerjaan terjadwal yang andal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Transaksi ACID terjamin&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ekosistem Spring lengkap&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💰 Ekonomi Progresif&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;0€ untuk mulai dan validasi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Biaya yang mengikuti pertumbuhan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Tanpa over-engineering yang dini&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🎯 Fleksibilitas Arsitektur&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Migrasi progresif tanpa rekonstruksi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Penambahan Spring Boot hanya jika diperlukan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Tidak ada vendor lock-in total&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Arsitektur evolutif&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_untuk_pergi_lebih_jauh&quot;&gt;Untuk Pergi Lebih Jauh&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sumber_daya_teknis&quot;&gt;Sumber Daya Teknis&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Dokumentasi Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/auth&quot;&gt;Panduan Otentikasi&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/database/postgres/row-level-security&quot;&gt;Keamanan Tingkat Baris&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/api&quot;&gt;API yang dibuat otomatis&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Documentasi Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/guides/tutorials/spring-boot-kotlin/&quot;&gt;Spring Boot dengan Kotlin&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/blog/2019/04/12/going-reactive-with-spring-coroutines-and-kotlin-flow&quot;&gt;Korutina dan Spring&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.spring.io/spring-security/reference/servlet/oauth2/resource-server/jwt.html&quot;&gt;Server Sumber Daya JWT&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;artikel tambahan :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Pengamanan API dengan JWT&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Optimalisasi performa PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;pola migrasi progresif&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Penanganan kesalahan dalam arsitektur terdistribusi&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kasus_penggunaan_nyata&quot;&gt;Kasus Penggunaan Nyata&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur hibrid ini digunakan dengan sukses di :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SaaS B2B&lt;/strong&gt;: Autentikasi Supabase, penagihan Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;pasar-pasar&lt;/strong&gt;: Katalog Supabase, transaksi Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Platform konten&lt;/strong&gt;: Artikel Supabase, analitik Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Alat internal&lt;/strong&gt;CRUD Supabase, workflows Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_daftar_periksa_awal&quot;&gt;Daftar Periksa Awal&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Phase 1 - Fondasi (Minggu 1)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Membuat akun Supabase - [ ] Mengonfigurasi proyek PostgreSQL - [ ] Mengaktifkan Auth (Google, GitHub) - [ ] Definisikan skema awal - [ ] Mengatur Row Level Security - [ ] Menguji API sejak JBake&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Tahap 2 - MVP (Minggu 2-3)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; mengimplementasikan halaman utama - [ ] Mengintegrasikan autentikasi OAuth2 - [ ] Membuat formulir CRUD - [ ] Mengkonfigurasi Storage untuk file - [ ] Men-deploy ke GitHub Pages - [ ] Uji dalam kondisi nyata&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Tahap 3 - Perkembangan (Sesuai kebutuhan)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Identifikasi kebutuhan logika kompleks - [ ] Membuat proyek Spring Boot jika diperlukan - [ ] Konfigurasi validasi JWT Supabase - [ ] Menghubungkan ke PostgreSQL Supabase - [ ] Migrasikan fitur kompleks - [ ] Implementasikan pekerjaan terjadwal - [ ] Mendeploy Spring Boot (Cloud Run, etc.)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_anti_patterns_yang_harus_dihindari&quot;&gt;Anti-Patterns yang harus dihindari&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ Jangan melakukan :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Menduplikasi data antara Supabase dan Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Buat dua basis data PostgreSQL terpisah&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kodekan otentikasi sendiri&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Menggunakan Spring Boot untuk CRUD sederhana&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Melakukan arsitektur berlebihan sejak awal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Abaikan Keamanan Level Baris Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ Lebih baik melakukan:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Membagikan satu basis data PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Biarkan Supabase mengelola otentikasi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Menggunakan Spring Boot hanya untuk kompleksitas&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Memulai sederhana, berkembang secara bertahap&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Memanfaatkan kekuatan setiap teknologi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Mengamankan dengan RLS pada tingkat basis data&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_perspektif_perkembangan&quot;&gt;Perspektif perkembangan&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_penambahan_kemampuan_baru&quot;&gt;Penambahan Kemampuan Baru&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Arsitektur Saat Ini&quot; #SkyBlue {
  [JBake]
  [Supabase]
  [Spring Boot]
}

rectangle &quot;Perkembangan yang Mungkin&quot; #LightYellow {

  package &quot;Kinerja&quot; {
    [Redis Cache]
    [CDN pour Assets]
    [PostgreSQL Replicas]
  }

  package &quot;pemantauan&quot; {
    [Grafana]
    [Prometheus]
    [Sentry]
  }

  package &quot;CI/CD&quot; {
    [GitHub Actions]
    [Tests Automatisés]
    [Déploiement Continu]
  }

  package &quot;Fitur&quot; {
    [Search (ElasticSearch)]
    [Queue (RabbitMQ)]
    [Event Sourcing]
  }
}

[Spring Boot] .down.&amp;gt; [Redis Cache] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Queue (RabbitMQ)] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Search (ElasticSearch)] : Peut ajouter

[Supabase] .down.&amp;gt; [PostgreSQL Replicas] : Peut ajouter

note bottom
  **Architecture extensible**
  Chaque ajout est indépendant
  Pas de refonte globale nécessaire
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_penskalaan_horizontal&quot;&gt;Penskalaan Horizontal&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Saat aplikasi Anda tumbuh, arsitektur hybridnya diskalakan secara alami:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Menskala otomatis hingga jutaan operasi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Read replicas untuk kinerja pembacaan&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pemulihan poin waktu untuk keamanan&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Beberapa instance di belakang load balancer&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Desain tanpa keadaan memudahkan penskalaan horizontal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kubernetes untuk orkestrasi jika diperlukan&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;PostgreSQL :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Partisi untuk tabel besar&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pooling koneksi (PgBouncer)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sharding benar-benar diperlukan (jarang)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_bukti_arkitektonik&quot;&gt;Bukti Arkitektonik&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_startup_saas_50k_pengguna&quot;&gt;Startup SaaS (50k pengguna)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Kami memulai 100% Supabase. Pada 5 ribu pengguna, kami menambahkan Spring Boot hanya untuk penagihan Stripe dan laporan bulanan. Satu tahun kemudian, 80% dari operasi kami masih melewati Supabase. Spring Boot hanya mengelola bagian kritis. Pemisahan ini memungkinkan kami menskalakan tanpa perlu merancang ulang. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_platform_e_learning_10_000_pengguna&quot;&gt;Platform E-learning (10.000 pengguna)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Otentikasi OAuth2 Supabase telah menghemat tiga minggu pengembangan kami. API yang otomatis dihasilkan mengelola seluruh katalog kursus kami. Spring Boot hanya digunakan untuk sertifikat PDF dan email progres. Arsitektur sederhana, mudah dipelihara, dan mudah dikembangkan. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_marketplace_b2b_3k_pengguna&quot;&gt;Marketplace B2B (3k pengguna)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&amp;lt;/think&amp;gt; (Empty output) Spring Boot mengelola transaksi antara pembeli dan penjual (kritik). Supabase mengelola seluruh hal lain: profil, pesan realtime, dokumen. Fakta bahwa mereka berbagi basis data PostgreSQL yang sama menghindarkan kita dari sinkronisasi yang kompleks. Pilihan arsitektur terbaik yang telah kita buat. &lt;em&gt;__&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sintesis_sebuah_paradigma_arsitektur_modern&quot;&gt;Sintesis : Sebuah Paradigma Arsitektur Modern&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur hibrid Supabase + Spring Boot merepresentasikan sebuah paradigma baru :&lt;strong&gt;spesialisasi arsitektur&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Paradigma lama&quot; #LightCoral {
  card &quot;Semua di Backend&quot; {
    [Auth]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [Storage]
    [Realtime]
  }
  note bottom
    Complexité maximale
    dès le jour 1
  end note
}

rectangle &quot;Paradigma Baru&quot; #LightGreen {
  card &quot;Supabase
(Kemudahan)&quot; {
    [Auth]
    [CRUD Simple]
    [Storage]
    [Realtime]
  }

  card &quot;Spring Boot\n(Diferensiasi)&quot; {
    [Logique Métier]
    [Jobs]
    [Intégrations]
  }

  note bottom
    Complexité progressive
    ajoutée seulement si nécessaire
  end note
}

[Ancien Paradigme] -right-&amp;gt; [Nouveau Paradigme] : Évolution

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Prinsip fundamental:&lt;/strong&gt;Jangan membangun apa yang sudah ada dalam bentuk layanan. Fokuslah pada apa yang membedakan aplikasi Anda.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prinsip_8020&quot;&gt;prinsip 80/20&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dalam sebagian besar aplikasi:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;80% dari operasi&lt;/strong&gt;adalah CRUD standar → Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;20% dari operasi&lt;/strong&gt;memerlukan logika bisnis → Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Aturan alami ini membenarkan arsitektur hibrid.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Distribusi Operasi&quot; {

  rectangle &quot;80% - Operasi Standar&quot; #LightGreen {
    [Lecture de données]
    [Création d&#39;entités]
    [Mise à jour simple]
    [Suppression]
    [Upload fichiers]
    [Authentification]

    note bottom: **Géré par Supabase**
  }

  rectangle &quot;20% - Logika Bisnis&quot; #Coral {
    [Calculs complexes]
    [Workflows multi-étapes]
    [Transactions critiques]
    [Intégrations tierces]
    [Jobs planifiés]

    note bottom: **Géré par Spring Boot**
  }
}

note right
  **Focus optimal :**
  Votre temps de développement
  concentré sur les 20% qui
  différencient votre produit
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_kesimpulan_akhir&quot;&gt;Kesimpulan Akhir&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Arsitektur hibrid bukanlah sebuah kompromi teknis, ini adalah&lt;strong&gt;keputusan strategis&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Dia memungkinkan Anda untuk :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✅ Memulai dengan cepat dengan MVP yang berfungsi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Memvalidasi pasar Anda tanpa investasi yang besar&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Berkembang secara bertahap ketika kompleksitas mengharuskannya&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Mengendalikan biaya Anda pada setiap tahap&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Memanfaatkan yang terbaik dari setiap teknologi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Menghindari over-engineering yang terlalu dini&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Menjaga fleksibilitas untuk masa depan&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Dia mewakili :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;🎯 &lt;strong&gt;Pragmatisme&lt;/strong&gt;: Setiap teknologi di mana ia unggul&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🚀&lt;strong&gt;kecepatan&lt;/strong&gt;: Time-to-market minimal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;💰&lt;strong&gt;ekonomi&lt;/strong&gt;: Biaya yang selaras dengan nilai&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🔮&lt;strong&gt;skalabilitas&lt;/strong&gt;: Arsitektur yang tumbuh dengan anda&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🛡️&lt;strong&gt;ketangguhan&lt;/strong&gt;: Layanan yang terbukti dan andal&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_langkah_selanjutnya_anda&quot;&gt;Langkah selanjutnya Anda&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Jika arsitektur ini Anda rasakan, ini adalah tempat untuk memulai:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Buat akun Supabase&lt;/strong&gt;(gratis)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Tentukan skema data minimal Anda&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Konfigurasikan otentikasi OAuth2&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Buat halaman JBake pertama Anda yang mengkonsumsi API&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Deploy ke GitHub Pages&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Anda akan memiliki MVP yang fungsional di&lt;strong&gt;beberapa hari&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Spring Boot akan datang secara alami ketika Anda membutuhkannya. Belum sebelum.&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Arsitektur hibrid adalah seni membangun tepat apa yang diperlukan, ketika diperlukan.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;Semoga sukses dalam pengembangan! 🚀&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;Bagikan artikel ini jika Anda berpikir bahwa artikel ini dapat membantu pengembang lain untuk membuat pilihan arsitektur yang tepat.&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

