&lt;li&gt;&lt;a href=&quot;#_pilihan_1_karakter_unicode&quot;&gt;Pilihan 1 : Karakter Unicode&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_opsi_2_gambar_eksternal&quot;&gt;Opsi 2 : Gambar Eksternal&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_opsi_3_peran_css_kustom&quot;&gt;Opsi 3 : Peran CSS Kustom&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_opsi_4_injeksi_html_solusi_yang_dipilih&quot;&gt;Opsi 4 : Injeksi HTML (solusi yang dipilih)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_solusi_injeksi_html_dengan&quot;&gt;Solusi : Injeksi HTML dengan &lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_prinsip_kerja&quot;&gt;Prinsip kerja&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_implementasi&quot;&gt;Implementasi&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_penjelasan_properti_css&quot;&gt;Penjelasan properti CSS&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_contoh_lengkap&quot;&gt;Contoh lengkap&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_optimisasi_dan_praktik_terbaik&quot;&gt;Optimisasi dan praktik terbaik&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_mengelola_warna_terang&quot;&gt;Mengelola warna terang&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_mengatur_ukuran_persegi&quot;&gt;Mengatur ukuran persegi&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_membuat_varian&quot;&gt;Membuat varian&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_lingkaran_berwarna&quot;&gt;lingkaran berwarna&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_persegi_dengan_batas_berwarna&quot;&gt;Persegi dengan batas berwarna&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_arsitektur_solusi&quot;&gt;Arsitektur solusi&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_manfaat_dan_batasan&quot;&gt;Manfaat dan batasan&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_kelebihan&quot;&gt;kelebihan&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_keterbatasan&quot;&gt;Keterbatasan&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_peningkatan_aksesibilitas&quot;&gt;Peningkatan aksesibilitas&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_contoh_konkret_dokumentasi_tema&quot;&gt;Contoh konkret: Dokumentasi tema&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kesimpulan&quot;&gt;Kesimpulan&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sumber_daya&quot;&gt;Sumber daya&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_pendahuluan&quot;&gt;Pendahuluan&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Saat menyusun dokumentasi teknis, terutama untuk panduan gaya atau spesifikasi antarmuka pengguna, seringkali diperlukan untuk menampilkan palet warna. AsciiDoc, meski sangat kuat untuk dokumentasi, tidak menyediakan sintaksis bawaan untuk menampilkan sampel warna. Artikel ini mengeksplorasi masalah dan menawarkan solusi yang elegan berbasis injeksi HTML.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_masalah&quot;&gt;Masalah&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_konteks_penggunaan&quot;&gt;Konteks penggunaan&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bayangkan bahwa Anda mendokumentasikan variabel CSS dari tema aplikasi web. Anda membutuhkan :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Daftar kode warna heksadesimal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Menampilkan pratinjau visual setiap warna&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Mempertahankan keterbacaan dokumen sumber&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Memastikan kompatibilitas dengan generator situs statis seperti JBake&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
skinparam packageStyle rectangle

actor &quot;Penulis Teknis&quot; as writer
actor &quot;Pembaca&quot; as reader

rectangle &quot;Dokumentasi AsciiDoc&quot; {
  usecase &quot;dokumentasikan palet warna&quot; as UC1
  usecase &quot;Tampilkan kode heksadesimal&quot; as UC2
  usecase &quot;Lihat warna&quot; as UC3
  usecase &quot;Menghasilkan situs statis&quot; as UC4
  usecase &quot;Melihat dokumentasi&quot; as UC5
}

writer --&amp;gt; UC1
UC1 ..&amp;gt; UC2 : include
UC1 ..&amp;gt; UC3 : include
UC1 --&amp;gt; UC4
UC4 --&amp;gt; UC5
UC5 &amp;lt;-- reader
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_pendekatan_yang_mungkin&quot;&gt;Pendekatan yang mungkin&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Beberapa solusi dapat dipertimbangkan untuk menampilkan warna dalam dokumen AsciiDoc :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam componentStyle rectangle

package &quot;Solusi mungkin&quot; {
  component &quot;Karakter Unicode&quot; as unicode
  component &quot;Gambar eksternal&quot; as images
  component &quot;Peran CSS khusus&quot; as css
  component &quot;Injeksi HTML&quot; as html
}

package &quot;Kriteria evaluasi&quot; {
  component &quot;kesederhanaan&quot; as simple
  component &quot;portabilitas&quot; as portable
  component &quot;Personalisasi&quot; as custom
  component &quot;Pemeliharaan&quot; as maintain
}

unicode -down-&amp;gt; simple : ✓
unicode -down-&amp;gt; portable : ✓
unicode -down-&amp;gt; custom : ✗

images -down-&amp;gt; simple : ✗
images -down-&amp;gt; portable : ✗
images -down-&amp;gt; custom : ✓

css -down-&amp;gt; simple : ~
css -down-&amp;gt; portable : ✗
css -down-&amp;gt; custom : ✓

html -down-&amp;gt; simple : ✓
html -down-&amp;gt; portable : ✓
html -down-&amp;gt; custom : ✓✓
html -down-&amp;gt; maintain : ✓

note right of html
  Solution recommandée
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_pilihan_1_karakter_unicode&quot;&gt;Pilihan 1 : Karakter Unicode&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Penggunaan karakter Unicode seperti`&amp;#9632;`(■) adalah sederhana tetapi terbatas:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* ■ --accent-color: #7952b3 (violet Bootstrap)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Keterbatasan&lt;/strong&gt; : Tidak ada kontrol atas warna, bergantung pada font sistem.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_opsi_2_gambar_eksternal&quot;&gt;Opsi 2 : Gambar Eksternal&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Buat gambar PNG atau SVG untuk setiap warna:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* image:colors/violet.svg[width=16] --accent-color: #7952b3&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Keterbatasan&lt;/strong&gt; : Pemeliharaan yang berat, perbantasan file, tidak ada sinkronisasi otomatis.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_opsi_3_peran_css_kustom&quot;&gt;Opsi 3 : Peran CSS Kustom&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Menentukan kelas CSS dan menerapkannya melalui peran AsciiDoc :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* [.color-violet]##■## --accent-color: #7952b3&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Keterbatasan&lt;/strong&gt; : Memerlukan lembar gaya eksternal, definisi sebelumnya semua warna yang mungkin.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_opsi_4_injeksi_html_solusi_yang_dipilih&quot;&gt;Opsi 4 : Injeksi HTML (solusi yang dipilih)&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Menggunakan makro``untuk menyisipkan HTML dengan gaya inline :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;
background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;]
--accent-color: #7952b3 (violet Bootstrap)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_solusi_injeksi_html_dengan&quot;&gt;Solusi : Injeksi HTML dengan &lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prinsip_kerja&quot;&gt;Prinsip kerja&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;makro``d&amp;#8217;AsciiDoc memungkinkan untuk menyisipkan konten mentah yang tidak akan ditafsirkan oleh prosesor AsciiDoc. Hal ini memungkinkan kita untuk langsung menyisipkan HTML dengan gaya CSS inline.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
participant &quot;Dokumen
AsciiDoc&quot; as doc
participant &quot;Prosesor\nAsciiDoc&quot; as processor
participant &quot;pass:[] macro&quot; as pass
participant &quot;HTML
akhir&quot; as html

doc -&amp;gt; processor : Analyse document
processor -&amp;gt; pass : Détecte pass:[]
pass -&amp;gt; processor : Retourne HTML brut
processor -&amp;gt; html : Insère sans transformation
html -&amp;gt; html : Navigateur applique styles
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_implementasi&quot;&gt;Implementasi&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Berikut struktur HTML untuk disisipkan:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;span style=&quot;display:inline-block;
             width:1em;
             height:1em;
             background:#7952b3;
             vertical-align:middle;
             margin-right:0.5em&quot;&amp;gt;
&amp;lt;/span&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_penjelasan_properti_css&quot;&gt;Penjelasan properti CSS&lt;/h4&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 25%;&quot;&gt;
&lt;col style=&quot;width: 75%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Properti&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;fungsi&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;display:inline-block&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Memungkinkan pengaturan lebar/tinggi sambil tetap berada dalam alur inline&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;width:1em; height:1em&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Ukuran persegi relatif terhadap ukuran font (responsif)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;background:#7952b3&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Warna yang ditampilkan (variabel sesuai kebutuhan Anda)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;vertical-align:middle&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Ratakan persegi dengan teks yang bersebelahan&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;margin-right:0.5em&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Jarak antara kotak dan teks&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_contoh_lengkap&quot;&gt;Contoh lengkap&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Berikut adalah contoh yang mendokumentasikan palet tema :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;== Thème Clair

* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#f8f9fa;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --bg-primary: `#f8f9fa` (blanc cassé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#212529;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --text-primary: `#212529` (noir très foncé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-color: `#7952b3` (violet Bootstrap)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#61428f;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-hover: `#61428f` (violet plus foncé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --card-bg: `#ffffff` (blanc)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Yang menghasilkan rendering berikut:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Tema Terang&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#f8f9fa;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --bg-primary:`#f8f9fa`(putih krem)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#212529;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --text-primary:`#212529`(hitam sangat gelap)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --accent-color:`#7952b3`(ungu Bootstrap)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#61428f;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --accent-hover:`#61428f`(ungu lebih gelap)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --card-bg:`#ffffff`(putih)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_optimisasi_dan_praktik_terbaik&quot;&gt;Optimisasi dan praktik terbaik&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_mengelola_warna_terang&quot;&gt;Mengelola warna terang&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Untuk warna-warni yang sangat terang (putih, abu-abu sangat terang), tambahkan garis tepi agar terlihat pada latar belakang putih:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;
background:#ffffff;border:1px solid #ccc;
vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;batas kelabu`border:1px solid #ccc`) memungkinkan untuk membatasi kotak putih di latar belakang putih.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_mengatur_ukuran_persegi&quot;&gt;Mengatur ukuran persegi&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Anda dapat menyesuaikan ukuran kotak sesuai kebutuhan Anda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span style=&quot;display:inline-block;width:1.5em;height:1.5em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] Grand carré
* pass:[&amp;lt;span style=&quot;display:inline-block;width:0.8em;height:0.8em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] Petit carré&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Penggunaan satuan`em`memastikan bahwa kotak menyesuaikan ukuran dengan ukuran huruf&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_membuat_varian&quot;&gt;Membuat varian&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Untuk kebutuhan spesifik, Anda dapat membuat bentuk-bentuk yang berbeda:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_lingkaran_berwarna&quot;&gt;lingkaran berwarna&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;border-radius:50%;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] Cercle violet&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_persegi_dengan_batas_berwarna&quot;&gt;Persegi dengan batas berwarna&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:3px solid #7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] Bordure violette&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_arsitektur_solusi&quot;&gt;Arsitektur solusi&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
package &quot;Alur kerja dokumentasi&quot; {
  [Document AsciiDoc\navec pass macro] as asciidoc
  [Processeur JBake] as jbake
  [Site HTML statique] as html
  [Navigateur Web] as browser
}

asciidoc --&amp;gt; jbake : 1. Compilation
jbake --&amp;gt; html : 2. Génération
html --&amp;gt; browser : 3. Affichage
browser --&amp;gt; browser : 4. Rendu CSS

note right of asciidoc
  Contient les balises
  pass:[] avec HTML inline
end note

note right of jbake
  Préserve le HTML
  dans pass:[]
end note

note right of browser
  Applique les styles
  inline CSS
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_manfaat_dan_batasan&quot;&gt;Manfaat dan batasan&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kelebihan&quot;&gt;kelebihan&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;Kemandirian&lt;/strong&gt; : Tidak ada ketergantungan pada file eksternal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;Portabilitas&lt;/strong&gt; : Berfungsi dengan semua prosesor AsciiDoc&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;Synchronisation&lt;/strong&gt; : Kode warnanya berada langsung di HTML&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;Fleksibilitas&lt;/strong&gt; : Penyesuaian lengkap gaya&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;Maintenance&lt;/strong&gt; : Modifikasi sederhana kode heksadesimal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;Kompatibilitas JBake&lt;/strong&gt; : Berfungsi dengan sempurna dengan generator situs statis&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_keterbatasan&quot;&gt;Keterbatasan&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✗ &lt;strong&gt;Verbosity&lt;/strong&gt; : Repetitive HTML code in the AsciiDoc source&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✗ &lt;strong&gt;Keterbacaan sumber&lt;/strong&gt; : Dokumen sumber kurang rapi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✗ &lt;strong&gt;Aksesibilitas&lt;/strong&gt; : Tidak ada teks alternatif bawaan (yang harus ditambahkan secara manual)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_peningkatan_aksesibilitas&quot;&gt;Peningkatan aksesibilitas&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Untuk membuat kotak dapat diakses oleh pembaca layar :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span role=&quot;img&quot; aria-label=&quot;Couleur violet Bootstrap&quot;
style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;
vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;]
--accent-color: `#7952b3` (violet Bootstrap)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Atribut`role=&quot;img&quot;` et `aria-label`Memungkinkan teknologi asistif untuk memahami dan menggambarkan konten visual.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_contoh_konkret_dokumentasi_tema&quot;&gt;Contoh konkret: Dokumentasi tema&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Berikut contoh lengkap yang mendokumentasikan beberapa tema:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Guide des couleurs de l&#39;application

== Thème Clair (`:root`)

* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#f8f9fa;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --bg-primary: `#f8f9fa` (blanc cassé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#212529;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --text-primary: `#212529` (noir très foncé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-color: `#7952b3` (violet Bootstrap)

== Thème Sombre (`[data-bs-theme=&quot;dark&quot;]`)

* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#212529;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --bg-primary: `#212529` (noir très foncé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:1px solid #999;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --text-primary: `#ffffff` (blanc)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#0d6efd;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-color: `#0d6efd` (bleu Bootstrap)

== Thème Contraste Élevé (`[data-bs-theme=&quot;high-contrast&quot;]`)

* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#000000;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --bg-primary: `#000000` (noir)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:1px solid #000;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --text-primary: `#ffffff` (blanc)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#00ff00;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-color: `#00ff00` (vert vif)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_kesimpulan&quot;&gt;Kesimpulan&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Injeksi HTML melalui makro``d&amp;#8217;AsciiDoc menawarkan solusi yang elegan dan pragmatis untuk menampilkan sampel warna dalam dokumentasi teknis. Meskipun sedikit bertele-tele, pendekatan ini menjamin portabilitas maksimal dan pemeliharaan yang disederhanakan.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Teknik ini tidak memerlukan konfigurasi eksternal, tidak memerlukan lembar gaya tambahan, dan berfungsi segera dengan JBake dan semua prosesor AsciiDoc standar.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Setelah Anda membuat kotak berwarna pertama Anda, cukup menyalin dan menempelkan kode HTML dan mengubah kode heksadesimal untuk dengan cepat membuat palet lengkap.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Teknik ini dapat diperluas ke kasus penggunaan lain yang memerlukan rendering visual khusus: ikon, badge, grafik sederhana, atau elemen visual apa pun yang memerlukan kontrol gaya yang tepat.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sumber_daya&quot;&gt;Sumber daya&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
