&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://jbake.org/docs/2.6.7/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Dokumentasi JBake&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://developer.mozilla.org/fr/docs/Web/CSS/color_value&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;MDN : Nilai warna CSS&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
