&lt;li&gt;&lt;a href=&quot;#_pasang_jbake&quot;&gt;&lt;strong&gt;Pasang JBake&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_memeriksa_instalasi_2&quot;&gt;Memeriksa instalasi&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_gradle_wrapper_praktik_terbaik_yang_mutlak&quot;&gt;5. Gradle Wrapper: Praktik terbaik yang mutlak&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_6_docker_dan_portainer_untuk_builds_yang_dapat_direproduksi_opsional&quot;&gt;6. Docker dan Portainer : Untuk Builds yang Dapat Direproduksi (Opsional)&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
