&lt;li&gt;&lt;a href=&quot;#_sintaks_dasar&quot;&gt;Sintaks dasar&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_judul_dan_bagian&quot;&gt;Judul dan bagian&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_teks_tebal_miring_dan_monospasi&quot;&gt;Teks tebal, miring dan monospasi&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_daftar_bullet_dan_daftar_bernomor&quot;&gt;Daftar bullet dan daftar bernomor&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tautan_dan_gambar&quot;&gt;Tautan dan gambar&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_blok_kode&quot;&gt;Blok kode&lt;/a&gt;&lt;/li&gt;
