&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Struktur Dasar dalam Google Apps Script&quot;&gt;[Struktur Dasar dalam Google Apps Script]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Tipe dan Variabel dalam Google Apps Script&quot;&gt;[Tipe dan Variabel dalam Google Apps Script]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Konstanta&quot;&gt;Variabel, dan Huruf di Google Apps Script&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Operasi dan Operator di Google Apps Script&quot;&gt;[Operasi dan Operator di Google Apps Script]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Var&quot;&gt;Let dan Const dalam Google Apps Script&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Struktur Kontrol dalam Google Apps Script&quot;&gt;[Struktur Kontrol dalam Google Apps Script]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Perulangan di Google Apps Script&quot;&gt;[Perulangan di Google Apps Script]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#_objek_di_google_apps_script&quot;&gt;Objek di Google Apps Script&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Fungsi di Google Apps Script&quot;&gt;[Fungsi di Google Apps Script]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Parameter dan Ruang Lingkup di Google Apps Script&quot;&gt;[Parameter dan Ruang Lingkup di Google Apps Script]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Operator Rest dan Operator Spread di Google Apps Script&quot;&gt;[Operator Rest dan Operator Spread di Google Apps Script]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
