                    &amp;lt;input type=&quot;submit&quot; value=&quot;Valider&quot; id=&quot;btn-submit&quot; /&amp;gt;
                &amp;lt;/form&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/div&amp;gt;

        &amp;lt;div class=&quot;absolute&quot;&amp;gt;
            &amp;lt;h2&amp;gt;Absolute&amp;lt;/h2&amp;gt;
