      &amp;lt;h2&amp;gt;Photo - Titre H2&amp;lt;/h2&amp;gt;
      &amp;lt;img src=&quot;./img-1.jpg&quot; alt=&quot;image-arbre&quot; height=&quot;200&quot; /&amp;gt;
    &amp;lt;/div&amp;gt;

    &amp;lt;div&amp;gt;
      &amp;lt;h3&amp;gt;Liste - Titre H3&amp;lt;/h3&amp;gt;
