&lt;li&gt;&lt;a href=&quot;#_untuk_menjalankan_tugas_dari_root_workingdir_maka_awali_tugas_dengan&quot;&gt;Untuk menjalankan tugas dari root workingDir, maka awali tugas dengan `:&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_untuk_memulai_ulang_tugas_yang_gagal_gunakan_opsi_rerun_tasks&quot;&gt;Untuk memulai ulang tugas yang gagal, gunakan opsi `--rerun-tasks&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_menjalankan_tugas_dalam_proyek_tertentu_dari_direktori_lain&quot;&gt;Menjalankan tugas dalam proyek tertentu dari direktori lain&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tampilkan_bantuan&quot;&gt;Tampilkan bantuan&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew --help&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_menetapkan_properti_sistem_jvm_d_system_prop&quot;&gt;Menetapkan properti sistem JVM: `-D, --system-prop&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew -Dmyprop=myvalue
#ou
./gradlew --system-prop myvalue&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_menetapkan_properti_proyek_untuk_skrip_build_pmypropmyvalue&quot;&gt;Menetapkan properti proyek untuk skrip build : `-Pmyprop=myvalue&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew -Pmyprop=myvalue
#ou
./gradlew --project-prop myvalue&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_menentukan_direktori_awal_gradle_nilai_defaultnya_adalah_direktori_saat_ini&quot;&gt;Menentukan direktori awal Gradle. Nilai defaultnya adalah direktori saat ini.&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew -p ~/src/next_startup
#ou
./gradlew --project-dir ~/src/next_startup&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_mengoverride_properti_param_component_melalui_baris_perintah&quot;&gt;Mengoverride properti &#39;param_component&#39; melalui baris perintah:&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew -Pparam_component=CUSTOM_VALUE&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_menambahkan_folder_ke_source_set_dalam_proyek_biasa_dengan_kotlin_dsl&quot;&gt;Menambahkan folder ke source-set dalam proyek biasa dengan kotlin dsl&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;sourceSets {
    getByName(&quot;test&quot;){
        java.srcDir(&quot;src/scripts/groovy&quot;)
    }
    getByName(&quot;test&quot;){
        java.srcDir(&quot;src/scripts/kscript&quot;)
    }
    getByName(&quot;test&quot;){
        java.srcDir(&quot;src/test/javascript&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_menambahkan_folder_ke_source_set_dalam_proyek_android_dengan_groovy_dsl&quot;&gt;Menambahkan folder ke source-set dalam proyek Android dengan Groovy DSL&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;android {
    sourceSets {
        main.java.srcDirs += &quot;src/main/../../../../ceelo/domain/src/main/java/&quot;
        test.java.srcDirs += &quot;src/test/../../../../ceelo/domain/src/test/java/&quot;
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_menghindari_membangun_dan_menguji_sub_modul&quot;&gt;Menghindari membangun dan menguji sub-modul&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;gradle membangun -x :excluded-module:memeriksa -x :excluded-module:merakit -x :excluded-module:membangun&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Memindahkan file&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;tasks.register(&quot;moveWebappNode&quot;) {
    doLast {
        ant.withGroovyBuilder {
            &quot;move&quot;(
                &quot;webapp/node_modules&quot; to &quot;$rootDir/webapp-src/node_modules&quot;,
            )
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_buat_arsip_sebuah_direktori&quot;&gt;Buat arsip sebuah direktori&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;tasks.register&amp;lt;Tar&amp;gt;(&quot;tarWebapp&quot;) {
    dependsOn(&quot;moveWebappNpm&quot;)
    group = WEBAPP
    description = &quot;tar webapp&quot;
    doLast {
        setOf(
            &quot;build&quot;,
            &quot;target&quot;,
            &quot;node_modules&quot;
        ).forEach { dir -&amp;gt; exclude { it.name .dir } }
        archiveFileName.set(&quot;webapp.tar&quot;)
        destinationDirectory.set(File(&quot;${rootDir.absolutePath}$sep$WEBAPP_SRC&quot;))
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_menampilkan_dependensi_build&quot;&gt;Menampilkan dependensi build&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;tasks.register(&quot;printDependencies&quot;) {
    description = &quot;print project dependencies&quot;
    group = WEBAPP
    doLast {
        println(&quot;${project.name} dependencies&quot;)
        mutableMapOf&amp;lt;String, Map&amp;lt;String, String&amp;gt;&amp;gt;(
            &quot;buildDependencies&quot; to buildDependencies,
            &quot;domainDeps&quot; to domainDeps,
            &quot;domainTestDeps&quot; to domainTestDeps,
        ).apply { putAll(appModules) }
            .forEach { module -&amp;gt;
                if (module.value.isNotEmpty()) {
                    println(&quot;${module.key}:&quot;)
                    module.value.forEach { println(dependency(it)) }
                    println()
                }
            }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_contoh_penggunaan_reduce_penggabungan_satu_daftar_dalam_sebuah_string&quot;&gt;Contoh penggunaan reduce : penggabungan satu daftar dalam sebuah string&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;tasks.register(&quot;printWebappSrc&quot;) {
    description = &quot;print webapp sources&quot;
    group = WEBAPP
    doLast {
        webAppSrc
            .reduce { acc, s -&amp;gt; &quot;$acc\n\t$s&quot; }
            .run { println(&quot;$WEBAPP_SRC: $this\n&quot;) }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_mendapatkan_deskripsi_tugas_tertentu&quot;&gt;Mendapatkan deskripsi tugas tertentu&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew -q help --task foo&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_untuk_menjalankan_tugas_dari_root_workingdir_maka_awali_tugas_dengan&quot;&gt;Untuk menjalankan tugas dari root workingDir, maka awali tugas dengan `:&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew :foo&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_untuk_memulai_ulang_tugas_yang_gagal_gunakan_opsi_rerun_tasks&quot;&gt;Untuk memulai ulang tugas yang gagal, gunakan opsi `--rerun-tasks&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew check --rerun-tasks&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_menjalankan_tugas_dalam_proyek_tertentu_dari_direktori_lain&quot;&gt;Menjalankan tugas dalam proyek tertentu dari direktori lain&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;pilihan`-p` (ou &lt;code&gt;--project-dir&lt;/code&gt;) memungkinkan menentukan jalur akses ke sebuah proyek Gradle dan mengeksekusi sebuah tugas di sana, bahkan jika direktori saat ini berbeda.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Contoh, untuk meluncurkan tugas`build`proyek yang terletak di`~/projets/mon-autre-projet`sambil berada di direktori lain:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew -p ~/projets/mon-autre-projet build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hal ini sangat berguna untuk membuat skrip aksi pada beberapa proyek dari satu lokasi pusat.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;lihat juga :&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.gradle.org/current/userguide/command_line_interface.html#sec:command_line_warnings&quot;&gt;referensi&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.gradle.org/current/userguide/command_line_interface.html#sec:command_line_options&quot;&gt;referensi&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://stackoverflow.com/a/36178581/837404&quot;&gt;diskusi&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;kelas sealed bukan merupakan enumerasi(kata kunci:enum).&lt;br&gt;
Dari Java, Anda mungkin tergoda untuk membebani enumerasi kontribusi fitur Anda: // Kode Java&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-java hljs&quot; data-lang=&quot;java&quot;&gt;enum PizzaOrderStatus {
    ORDER_RECEIVED,
    PIZZA_BEING_MADE,
    OUT_FOR_DELIVERY,
    COMPLETED;
    public PizzaOrderStatus nextStatus() {
        switch (this) {
        case ORDER_RECEIVED: return PIZZA_BEING_MADE;
        case PIZZA_BEING_MADE: return OUT_FOR_DELIVERY;
        case OUT_FOR_DELIVERY: return COMPLETED;
        case COMPLETED:return COMPLETED;
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Alih-alih, Anda dapat menggunakan kelas sealed :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;sealed class PizzaOrderStatus(protected val orderId: Int) {
    abstract fun nextStatus() : PizzaOrderStatus
    class OrderReceived(orderId: Int) : PizzaOrderStatus(orderId) {
        override fun nextStatus(): PizzaOrderStatus {
            return PizzaBeingMade(orderId)
        }
    }
    class PizzaBeingMade(orderId: Int) : PizzaOrderStatus(orderId) {
        override fun nextStatus(): PizzaOrderStatus {
            return OutForDelivery(orderId)
        }
    }
    class OutForDelivery(orderId: Int) : PizzaOrderStatus(orderId) {
        override fun nextStatus(): PizzaOrderStatus {
            return Completed(orderId)
        }
    }
    class Completed(orderId: Int) : PizzaOrderStatus(orderId) {
        override fun nextStatus(): PizzaOrderStatus {
            return this
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Keuntungan dari pendekatan ini adalah bahwa sekarang kami dapat mengirim data dengan status:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;var status: PizzaOrderStatus = OrderReceived(123)
while (status !is Completed) {
    status = when (status) {
        is OrderReceived -&amp;gt; status.nextStatus()
        is PizzaBeingMade -&amp;gt; status.nextStatus()
        is OutForDelivery -&amp;gt; status.nextStatus()
        is Completed -&amp;gt; status
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Umumnya, sealed classes bagus jika Anda ingin memiliki data terkait dengan satu Negara.&lt;/p&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_peta_pikir&quot;&gt;Peta pikir&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;span class=&quot;image&quot;&gt;&lt;img src=&quot;../../diagram/training_kotlin.png&quot; alt=&quot;training_kotlin&quot;&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_pemrograman_fungsional&quot;&gt;Pemrograman fungsional&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Latihan diambil dari buku:&lt;br&gt;
Pemrograman fungsional dalam Kotlin oleh tutorial&lt;br&gt;
Ditulis oleh Massimo Carli&lt;br&gt;
repo: &lt;a href=&quot;https://github.com/kodecocodes/fpk-materials&quot; class=&quot;bare&quot;&gt;https://github.com/kodecocodes/fpk-materials&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sintaksis&quot;&gt;Sintaksis&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_firstprogramtest&quot;&gt;FirstProgramTest&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;konsep: tampilan layar, fungsi&lt;br&gt;
FirstProgramTest:https://github.com/cheroliv/cheroliv.com/blob/master/codes/src/test/kotlin/programming/FirstProgramTest.kt[sumber]+&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_concatfunctiontest&quot;&gt;ConcatFunctionTest&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;konsep: memori, variabel, nilai, objek, ekstensi fungsi&lt;br&gt;
ExampleUnitTest: &lt;a href=&quot;https://github.com/cheroliv/cheroliv.com/blob/master/codes/src/test/kotlin/programming/ConcatFunctionTest.kt&quot;&gt;sumber&lt;/a&gt;+&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_birthdaymessagetestoutput&quot;&gt;BirthdayMessageTestOutput&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;konsep: himpunan, loop&lt;br&gt;
&lt;a href=&quot;https://developer.android.com/codelabs/basic-android-kotlin-training-first-kotlin-program?continue=https%3A%2F%2Fdeveloper.android.com%2Fcourses%2Fpathways%2Fandroid-basics-kotlin-one%23codelab-https%3A%2F%2Fdeveloper.android.com%2Fcodelabs%2Fbasic-android-kotlin-training-first-kotlin-program&quot;&gt;Pengantar kotlin&lt;/a&gt;&lt;br&gt;
BirthdayMessageTestOutput:https://github.com/cheroliv/cheroliv.com/blob/master/codes/src/test/kotlin/programming/BirthdayMessageTestOutput.kt[sumber]+&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kursus_kotlin&quot;&gt;Kursus kotlin&lt;/h3&gt;
&lt;div class=&quot;videoblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;iframe src=&quot;https://www.youtube.com/embed/YRjY3jRrQYY?rel=0&quot; frameborder=&quot;0&quot; allowfullscreen&gt;&lt;/iframe&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tutorial_koleksi_di_java&quot;&gt;Tutorial koleksi di Java&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.oracle.com/javase/tutorial/collections/index.html&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Koleksi&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
